import { BilingualText } from '../types';

export type GrammarLevel = 'A1' | 'A2' | 'B1';
export interface GrammarExercise {
  id: string;
  prompt: BilingualText;
  sentence?: string;
  options: string[];
  answer: number;
  explanation: BilingualText;
}
export interface GrammarLevelContent {
  label: BilingualText;
  focus: BilingualText;
  explanation: BilingualText;
  example: BilingualText;
  exercises: GrammarExercise[];
}
export interface GrammarTopic {
  id: string;
  title: BilingualText;
  subtitle: BilingualText;
  levels: Record<GrammarLevel, GrammarLevelContent>;
}

const exercise = (id: string, prompt: BilingualText, options: string[], answer: number, explanation: BilingualText, sentence?: string): GrammarExercise =>
  ({ id, prompt, options, answer, explanation, sentence });

export const ITALIAN_GRAMMAR_TOPICS: GrammarTopic[] = [
  {
    id: 'articles', title: { en: 'Articles · Articoli', it: 'Articoli', pt: 'Artigos · Articoli', es: 'Artículos · Articoli', fr: 'Articles · Articoli', de: 'Artikel · Articoli' }, subtitle: { en: 'Choose the article that agrees with the noun.', it: 'Scegli l’articolo che concorda con il nome.', pt: 'Escolha o artigo que concorda com o substantivo.', es: 'Elige el artículo que concuerda con el sustantivo.', fr: 'Choisis l’article qui s’accorde avec le nom.', de: 'Wähle den Artikel, der zum Substantiv passt.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Gender, number and common definite/indefinite articles.', 'Genere, numero e articoli determinativi/indeterminativi più comuni.'], explanation: ['Italian articles change according to the noun’s gender (masculine/feminine) and number (singular/plural). Use il/i, lo/gli, la/le and l’ for definite articles; un/uno and una/un’ for indefinite articles.', 'Gli articoli italiani cambiano in base al genere (maschile/femminile) e al numero (singolare/plurale). Si usano il/i, lo/gli, la/le e l’ per gli articoli determinativi; un/uno e una/un’ per gli indeterminativi.'], example: ['un libro · uno studente · un’amica · la casa · gli zaini', 'un libro · uno studente · un’amica · la casa · gli zaini'], exercises: [exercise('art-a1-1', ['Choose the correct article: ___ amico.', 'Scegli l’articolo corretto: ___ amico.'], ['un', 'uno', 'una'], 0, ['Amico is masculine and begins with a vowel: use un (no apostrophe).', 'Amico è maschile e inizia per vocale: si usa un (senza apostrofo).'], '___ amico'), exercise('art-a1-2', ['Complete: ___ studente is here.', 'Completa: ___ studente è qui.'], ['Il', 'Lo', 'La'], 1, ['Use lo before s + consonant, z, gn, ps and similar sounds.', 'Si usa lo davanti a s + consonante, z, gn, ps e suoni simili.'], '___ studente è qui'), exercise('art-a1-3', ['Choose the feminine plural article: ___ ragazze.', 'Scegli l’articolo femminile plurale: ___ ragazze.'], ['I', 'Gli', 'Le'], 2, ['Ragazze is feminine plural, so the article is le.', 'Ragazze è femminile plurale, quindi l’articolo è le.'], '___ ragazze'), exercise('art-a1-4', ['Choose the correct indefinite article: ___ studente.', 'Scegli l’articolo indeterminativo corretto: ___ studente.'], ['un', 'uno', 'una'], 1, ['Studente begins with s + consonant, so use uno.', 'Studente inizia con s + consonante, quindi si usa uno.'], '___ studente'), exercise('art-a1-5', ['Complete: Ho ___ amica a Roma.', 'Completa: Ho ___ amica a Roma.'], ['un', 'un’', 'una'], 1, ['Amica is feminine singular and begins with a vowel: un’amica.', 'Amica è femminile singolare e inizia per vocale: un’amica.']), exercise('art-a1-6', ['Choose the correct plural article: ___ zaini sono nuovi.', 'Scegli l’articolo plurale corretto: ___ zaini sono nuovi.'], ['I', 'Gli', 'Le'], 1, ['Zaini is masculine plural and begins with z: gli zaini.', 'Zaini è maschile plurale e inizia per z: gli zaini.']), exercise('art-a1-7', ['Choose the correct article: ___ zaino.', 'Scegli l’articolo corretto: ___ zaino.'], ['il', 'lo', 'la'], 1, ['Zaino is masculine and begins with z: use lo.', 'Zaino è maschile e inizia per z: si usa lo.'], '___ zaino'), exercise('art-a1-8', ['Choose the correct article: ___ casa.', 'Scegli l’articolo corretto: ___ casa.'], ['il', 'la', 'lo'], 1, ['Casa is feminine singular beginning with a consonant: la casa.', 'Casa è femminile singolare e inizia con consonante: la casa.'], '___ casa'), exercise('art-a1-9', ['Choose the correct article: ___ orologio.', 'Scegli l’articolo corretto: ___ orologio.'], ['il', 'l’', 'lo'], 1, ['Orologio is masculine beginning with a vowel: l’orologio.', 'Orologio è maschile e inizia per vocale: l’orologio.'], '___ orologio'), exercise('art-a1-10', ['Choose the plural: ___ gatti.', 'Scegli il plurale: ___ gatti.'], ['i', 'gli', 'le'], 0, ['Gatti is masculine plural beginning with a regular consonant: i gatti.', 'Gatti è maschile plurale e inizia con consonante semplice: i gatti.'], '___ gatti'), exercise('art-a1-11', ['Choose the indefinite article: ___ ora.', 'Scegli l’articolo indeterminativo: ___ ora.'], ['un', 'un’', 'uno'], 1, ['Ora is feminine and begins with a vowel: un’ora.', 'Ora è femminile e inizia per vocale: un’ora.'], '___ ora')]},
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Article agreement in longer noun phrases and vowel/special-sound cases.', 'Accordo dell’articolo in gruppi nominali più lunghi e casi particolari.'], explanation: ['Check the noun, not the adjective that follows. L’ is used before a vowel for both genders in the singular; the plural reveals the gender: gli amici, le amiche.', 'Controlla il nome, non l’aggettivo che segue. L’ si usa davanti a vocale per entrambi i generi al singolare; il plurale mostra il genere: gli amici, le amiche.'], example: ['L’amica simpatica arriva; gli amici simpatici arrivano.', 'L’amica simpatica arriva; gli amici simpatici arrivano.'], exercises: [exercise('art-a2-1', ['Complete the sentence.', 'Completa la frase.'], ['Gli', 'I', 'Le'], 0, ['Amici is masculine plural and begins with a vowel: gli amici.', 'Amici è maschile plurale e inizia per vocale: gli amici.'], '___ amici arrivano domani'), exercise('art-a2-2', ['Choose the correct phrase.', 'Scegli il gruppo nominale corretto.'], ['un’amico interessante', 'un amico interessante', 'uno amico interessante'], 1, ['Before a masculine noun beginning with a vowel, write un without an apostrophe.', 'Davanti a un nome maschile che inizia per vocale si scrive un senza apostrofo.'], '___ interessante'), exercise('art-a2-3', ['Complete: Ho visto ___ belle case.', 'Completa: Ho visto ___ belle case.'], ['i', 'le', 'gli'], 1, ['Case is feminine plural, so use le.', 'Case è femminile plurale, quindi si usa le.'], 'Ho visto ___ belle case'), exercise('art-a2-4', ['Complete: Ho comprato ___ libro interessante.', 'Completa: Ho comprato ___ libro interessante.'], ['uno', 'un', 'una'], 1, ['Libro is masculine singular and begins with a regular consonant: un libro.', 'Libro è maschile singolare e inizia con una consonante semplice: un libro.']), exercise('art-a2-5', ['Complete: ___ friends of Sara arrive at eight.', 'Completa: ___ amiche di Sara arrivano alle otto.'], ['Le', 'Gli', 'I'], 0, ['Amiche is feminine plural: le amiche.', 'Amiche è femminile plurale: le amiche.']), exercise('art-a2-6', ['Choose the correct contraction: Vado ___ stadio.', 'Scegli la preposizione articolata corretta: Vado ___ stadio.'], ['al', 'allo', 'all’'], 1, ['Stadio begins with s + consonant: a + lo becomes allo.', 'Stadio inizia con s + consonante: a + lo diventa allo.']), exercise('art-a2-7', ['Complete: ___ studenti sono in classe.', 'Completa: ___ studenti sono in classe.'], ['I', 'Gli', 'Le'], 1, ['Studenti is masculine plural beginning with s + consonant: gli studenti.', 'Studenti è maschile plurale e inizia con s + consonante: gli studenti.'], '___ studenti sono in classe'), exercise('art-a2-8', ['Choose the contraction: Il libro ___ ragazzo.', 'Scegli la preposizione articolata: Il libro ___ ragazzo.'], ['del', 'dello', 'dell’'], 0, ['Di + il becomes del before ragazzo: il libro del ragazzo.', 'Di + il diventa del davanti a ragazzo: il libro del ragazzo.'], 'Il libro ___ ragazzo'), exercise('art-a2-9', ['Complete: Vado ___ zoo con i bambini.', 'Completa: Vado ___ zoo con i bambini.'], ['al', 'allo', 'all’'], 1, ['Zoo begins with z, so a + lo becomes allo.', 'Zoo inizia per z, quindi a + lo diventa allo.'], 'Vado ___ zoo'), exercise('art-a2-10', ['Choose the correct phrase.', 'Scegli il gruppo corretto.'], ['un’ora intera', 'un ora intera', 'uno ora intera'], 0, ['Una becomes un’ before the feminine noun ora, which begins with a vowel.', 'Una diventa un’ davanti al nome femminile ora, che inizia per vocale.']), exercise('art-a2-11', ['Complete: ___ amiche di Luca sono simpatiche.', 'Completa: ___ amiche di Luca sono simpatiche.'], ['Le', 'Gli', 'I'], 0, ['Amiche is feminine plural: le amiche.', 'Amiche è femminile plurale: le amiche.'], '___ amiche di Luca')]},
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Combine article choice with agreement and sentence meaning.', 'Combina la scelta dell’articolo con l’accordo e il significato della frase.'], explanation: ['At B1, choose articles automatically in full sentences and notice how article choice interacts with prepositions (nel, alla, degli) and adjective agreement.', 'Al livello B1 scegli gli articoli con naturalezza nelle frasi complete e osserva come si combinano con le preposizioni (nel, alla, degli) e con l’accordo degli aggettivi.'], example: ['Nel vecchio edificio ci sono degli uffici e delle aule luminose.', 'Nel vecchio edificio ci sono degli uffici e delle aule luminose.'], exercises: [exercise('art-b1-1', ['Choose the grammatically correct sentence.', 'Scegli la frase grammaticalmente corretta.'], ['Gli studenti hanno comprato dei libri nuovi.', 'I studenti hanno comprato degli libri nuovi.', 'Gli studenti hanno comprato delle libri nuovi.'], 0, ['Gli agrees with masculine plural studenti; dei agrees with masculine plural libri.', 'Gli concorda con studenti maschile plurale; dei concorda con libri maschile plurale.']), exercise('art-b1-2', ['Complete: Parliamo con ___ insegnante nuova.', 'Completa: Parliamo con ___ insegnante nuova.'], ['il', 'la', 'l’'], 2, ['Insegnante is singular and begins with a vowel; l’ works for either gender. The adjective nuova identifies the feminine referent.', 'Insegnante è singolare e inizia per vocale: si usa l’. L’aggettivo nuova indica il referente femminile.'], 'Parliamo con ___ insegnante nuova'), exercise('art-b1-3', ['Correct the phrase by choosing its proper form.', 'Correggi il gruppo scegliendo la forma corretta.'], ['uno amica gentile', 'un’amica gentile', 'un amica gentile'], 1, ['Una becomes un’ before a feminine noun beginning with a vowel.', 'Una diventa un’ davanti a un nome femminile che inizia per vocale.']), exercise('art-b1-4', ['Choose the fully correct sentence.', 'Scegli la frase completamente corretta.'], ['Nello zaino ci sono degli astucci e delle penne.', 'Nel zaino ci sono dei astucci e delle penne.', 'Nello zaino ci sono degli astucci e dei penne.'], 0, ['In + lo = nello (zaino, z-); degli before astucci (vowel); delle before penne (feminine plural).', 'In + lo = nello (zaino, z-); degli davanti ad astucci (vocale); delle davanti a penne (femminile plurale).']), exercise('art-b1-5', ['Complete: Ho parlato con ___ psicologo nuovo.', 'Completa: Ho parlato con ___ psicologo nuovo.'], ['il', 'lo', 'l’'], 1, ['Psicologo begins with ps-, so the article is lo.', 'Psicologo inizia con ps-, quindi l’articolo è lo.'], 'con ___ psicologo nuovo')] }
    }
  },
  {
    id: 'pronouns', title: { en: 'Pronouns · Pronomi', it: 'Pronomi', pt: 'Pronomes · Pronomi', es: 'Pronombres · Pronomi', fr: 'Pronoms · Pronomi', de: 'Pronomen · Pronomi' }, subtitle: { en: 'Replace names and things naturally with pronouns.', it: 'Sostituisci persone e cose con i pronomi in modo naturale.', pt: 'Substitua pessoas e coisas naturalmente por pronomes.', es: 'Sustituye personas y cosas de forma natural con pronombres.', fr: 'Remplace les personnes et les choses naturellement par des pronoms.', de: 'Ersetze Personen und Dinge natürlich durch Pronomen.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Subject pronouns and basic direct objects.', 'Pronomi soggetto e complemento oggetto di base.'], explanation: ['Subject pronouns say who performs the action: io, tu, lui/lei, noi, voi, loro. Italian often omits them because the verb ending already identifies the subject.', 'I pronomi soggetto indicano chi compie l’azione: io, tu, lui/lei, noi, voi, loro. In italiano spesso si omettono perché la desinenza del verbo indica già il soggetto.'], example: ['(Io) studio italiano. · Maria? La vedo.', '(Io) studio italiano. · Maria? La vedo.'], exercises: [exercise('pro-a1-1', ['Which pronoun means “we”?', 'Quale pronome significa “we”?'], ['voi', 'noi', 'loro'], 1, ['Noi means we; voi means you plural; loro means they.', 'Noi significa we; voi significa you plurale; loro significa they.']), exercise('pro-a1-2', ['Replace “Marco” with a subject pronoun.', 'Sostituisci “Marco” con un pronome soggetto.'], ['Lei', 'Lui', 'Loro'], 1, ['Marco is masculine singular: lui.', 'Marco è maschile singolare: lui.'], 'Marco parla. → ___ parla.'), exercise('pro-a1-3', ['Replace “la pizza” with a direct object pronoun.', 'Sostituisci “la pizza” con un pronome diretto.'], ['lo', 'la', 'li'], 1, ['La pizza is feminine singular, so use la.', 'La pizza è femminile singolare, quindi si usa la.'], 'Mangio la pizza. → ___ mangio.'), exercise('pro-a1-4', ['Which subject pronoun can replace “Paolo e io”?', 'Quale pronome soggetto può sostituire “Paolo e io”?'], ['voi', 'noi', 'loro'], 1, ['Paolo and I means we: noi.', 'Paolo e io significa noi.']), exercise('pro-a1-5', ['Choose the direct pronoun for “i ragazzi”.', 'Scegli il pronome diretto per “i ragazzi”.'], ['li', 'le', 'la'], 0, ['I ragazzi is masculine plural: li.', 'I ragazzi è maschile plurale: li.']), exercise('pro-a1-6', ['Complete: Anna and I? ___ vedo ogni giorno.', 'Completa: Anna e io? ___ vedo ogni giorno.'], ['Ci', 'Vi', 'Le'], 0, ['The speaker includes themself and Anna: ci (us).', 'Il parlante include sé stesso e Anna: ci (noi).']), exercise('pro-a1-7', ['Replace “il caffè”: Bevo il caffè.', 'Sostituisci “il caffè”: Bevo il caffè.'], ['la', 'lo', 'li'], 1, ['Il caffè is masculine singular: lo.', 'Il caffè è maschile singolare: lo.'], 'Bevo il caffè. → ___ bevo.'), exercise('pro-a1-8', ['Which pronoun means “they” (masculine)?', 'Quale pronome significa “they” (maschile)?'], ['loro', 'voi', 'noi'], 0, ['Loro means they; it is the same for masculine and feminine.', 'Loro significa they; è uguale per maschile e femminile.']), exercise('pro-a1-9', ['Replace “le ragazze”: Vedo le ragazze.', 'Sostituisci “le ragazze”: Vedo le ragazze.'], ['li', 'le', 'la'], 1, ['Le ragazze is feminine plural: le.', 'Le ragazze è femminile plurale: le.'], 'Vedo le ragazze. → ___ vedo.'), exercise('pro-a1-10', ['Which subject pronoun replaces “tu e Maria”?', 'Quale pronome soggetto sostituisce “tu e Maria”?'], ['noi', 'voi', 'loro'], 1, ['You + another person means voi.', 'Tu + un’altra persona significa voi.']), exercise('pro-a1-11', ['Replace “il gelato”: Mangio il gelato.', 'Sostituisci “il gelato”: Mangio il gelato.'], ['lo', 'la', 'le'], 0, ['Il gelato is masculine singular: lo.', 'Il gelato è maschile singolare: lo.'], 'Mangio il gelato. → ___ mangio.')]},
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Direct and indirect pronouns in everyday sentences.', 'Pronomi diretti e indiretti nelle frasi quotidiane.'], explanation: ['Direct pronouns answer “who/what?” (lo, la, li, le). Indirect pronouns answer “to whom?” (mi, ti, gli, le, ci, vi). They normally come before a conjugated verb.', 'I pronomi diretti rispondono a “chi?/che cosa?” (lo, la, li, le). Gli indiretti rispondono a “a chi?” (mi, ti, gli, le, ci, vi). Di solito precedono il verbo coniugato.'], example: ['Compro i biglietti → Li compro. · Telefono a Luca → Gli telefono.', 'Compro i biglietti → Li compro. · Telefono a Luca → Gli telefono.'], exercises: [exercise('pro-a2-1', ['Replace “i libri”: Leggo i libri.', 'Sostituisci “i libri”: Leggo i libri.'], ['Le leggo.', 'Li leggo.', 'Lo leggo.'], 1, ['I libri is masculine plural: li.', 'I libri è maschile plurale: li.']), exercise('pro-a2-2', ['“I call Giulia” → Chiamo Giulia. Choose the replacement.', '“Chiamo Giulia.” Scegli la sostituzione.'], ['La chiamo.', 'Le chiamo.', 'Lo chiamo.'], 0, ['Giulia is the direct object, feminine singular: la.', 'Giulia è complemento oggetto femminile singolare: la.']), exercise('pro-a2-3', ['“I write to Paolo” → Scrivo a Paolo. Choose the replacement.', '“Scrivo a Paolo.” Scegli la sostituzione.'], ['Lo scrivo.', 'Gli scrivo.', 'La scrivo.'], 1, ['A Paolo is an indirect object: gli.', 'A Paolo è complemento indiretto: gli.']), exercise('pro-a2-4', ['Replace “le mele”: Compro le mele.', 'Sostituisci “le mele”: Compro le mele.'], ['Le compro.', 'Li compro.', 'Gli compro.'], 0, ['Le mele is feminine plural: le.', 'Le mele è femminile plurale: le.']), exercise('pro-a2-5', ['Choose the indirect pronoun: Scrivo a mia madre.', 'Scegli il pronome indiretto: Scrivo a mia madre.'], ['La scrivo.', 'Le scrivo.', 'Lo scrivo.'], 1, ['A mia madre answers “to whom?”: le.', 'A mia madre risponde a “a chi?”: le.']), exercise('pro-a2-6', ['Choose the correct position: “I see them”.', 'Scegli la posizione corretta: “Li vedo”.'], ['Vedo li.', 'Li vedo.', 'Vedo gli.'], 1, ['A direct object pronoun normally comes before a conjugated verb.', 'Il pronome diretto precede normalmente il verbo coniugato.']), exercise('pro-a2-7', ['Replace “a Maria”: Telefono a Maria.', 'Sostituisci “a Maria”: Telefono a Maria.'], ['La telefono.', 'Le telefono.', 'Gli telefono.'], 1, ['A Maria is indirect, feminine: le.', 'A Maria è complemento indiretto, femminile: le.']), exercise('pro-a2-8', ['Replace “a Marco e Luca”: Scrivo a Marco e Luca.', 'Sostituisci “a Marco e Luca”: Scrivo a Marco e Luca.'], ['Gli scrivo.', 'Le scrivo.', 'Li scrivo.'], 0, ['To them (plural) is gli in modern spoken Italian; it answers “to whom?”.', 'A loro si rende con gli nell’italiano parlato moderno; risponde a “a chi?”.']), exercise('pro-a2-9', ['Which sentence uses “ne” correctly?', 'Quale frase usa “ne” correttamente?'], ['Ho due sorelle. → Ne ho due.', 'Ho due sorelle. → Le ho due.', 'Ho due sorelle. → Ci ho due.'], 0, ['Ne replaces a partitive or a quantity: ne ho due (two of them).', 'Ne sostituisce un partitivo o una quantità: ne ho due.']), exercise('pro-a2-10', ['Complete with “ne”: Quante mele vuoi? → ___ voglio tre.', 'Completa con “ne”: Quante mele vuoi? → ___ voglio tre.'], ['Le', 'Ne', 'Li'], 1, ['With a number, ne carries “of them”: ne voglio tre.', 'Con un numero, ne esprime “di esse”: ne voglio tre.']), exercise('pro-a2-11', ['Replace “la verdura”: Compro la verdura.', 'Sostituisci “la verdura”: Compro la verdura.'], ['La compro.', 'Le compro.', 'Ne compro.'], 0, ['La verdura is a whole, definite feminine singular object: la.', 'La verdura è un oggetto definito femminile singolare: la.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Use pronouns in connected speech and distinguish direct/indirect roles.', 'Usa i pronomi nel discorso e distingui la funzione diretta e indiretta.'], explanation: ['At B1, identify the role of the noun before replacing it. With a modal verb, the pronoun can precede the conjugated verb or attach to the infinitive: Lo voglio comprare / Voglio comprarlo.', 'Al livello B1 individua la funzione del nome prima di sostituirlo. Con un verbo servile il pronome può precedere il verbo coniugato o unirsi all’infinito: Lo voglio comprare / Voglio comprarlo.'], example: ['Hai visto Anna? Sì, l’ho vista ieri. · Posso aiutarti / Ti posso aiutare.', 'Hai visto Anna? Sì, l’ho vista ieri. · Posso aiutarti / Ti posso aiutare.'], exercises: [exercise('pro-b1-1', ['Choose the natural replacement: “Ho incontrato Marta.”', 'Scegli la sostituzione naturale: “Ho incontrato Marta.”'], ['Le ho incontrato.', 'L’ho incontrata.', 'La ho incontrato.'], 1, ['The direct pronoun la becomes l’ before ho; the past participle agrees: incontrata.', 'Il pronome diretto la diventa l’ davanti a ho; il participio concorda: incontrata.']), exercise('pro-b1-2', ['Replace “a noi”: Il professore spiega la regola a noi.', 'Sostituisci “a noi”: Il professore spiega la regola a noi.'], ['Ci spiega la regola.', 'La spiega a noi.', 'Gli spiega la regola.'], 0, ['A noi is indirect: ci.', 'A noi è complemento indiretto: ci.']), exercise('pro-b1-3', ['Choose both natural forms.', 'Scegli entrambe le forme naturali.'], ['Lo posso fare / Posso farlo', 'Gli posso fare / Posso gli fare', 'La posso fare / Posso farla (for “il compito”)'], 0, ['For a masculine singular direct object: lo posso fare or posso farlo.', 'Per un complemento oggetto maschile singolare: lo posso fare oppure posso farlo.']), exercise('pro-b1-4', ['Combine the pronouns: Do il libro a Maria.', 'Unisci i pronomi: Do il libro a Maria.'], ['Glielo do.', 'Gliela do.', 'Lo le do.'], 0, ['Indirect le + direct lo (il libro) combine to glielo.', 'L’indiretto le + il diretto lo (il libro) formano glielo.']), exercise('pro-b1-5', ['Combine the pronouns: Porto le chiavi a Paolo.', 'Unisci i pronomi: Porto le chiavi a Paolo.'], ['Gliele porto.', 'Glieli porto.', 'Gli le porto.'], 0, ['Indirect gli + direct le (le chiavi) become gliele.', 'L’indiretto gli + il diretto le (le chiavi) formano gliele.']), exercise('pro-b1-6', ['Choose the sentence where “ne” is wrong.', 'Scegli la frase in cui “ne” è sbagliato.'], ['Hai chiamato Marco? → Sì, ne ho chiamato.', 'Vuoi del pane? → Sì, ne voglio.', 'Quanti libri leggi? → Ne leggo due.'], 0, ['Marco is a definite whole object: use l’ho chiamato, not ne.', 'Marco è un oggetto definito: si dice l’ho chiamato, non ne.'])] }
    }
  },
  {
    id: 'passato-prossimo', title: { en: 'Passato prossimo', it: 'Passato prossimo', pt: 'Passato prossimo', es: 'Passato prossimo', fr: 'Passato prossimo', de: 'Passato prossimo' }, subtitle: { en: 'Talk about completed events in the past.', it: 'Racconta eventi conclusi nel passato.', pt: 'Fale sobre eventos concluídos no passado.', es: 'Habla de acciones terminadas en el pasado.', fr: 'Parle d’événements terminés au passé.', de: 'Sprich über abgeschlossene Ereignisse in der Vergangenheit.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Auxiliary + past participle: avere or essere.', 'Ausiliare + participio passato: avere o essere.'], explanation: ['The passato prossimo is formed with avere or essere in the present + a past participle: ho mangiato, sono arrivato/a. Many transitive verbs use avere; many movement/change-of-state and reflexive verbs use essere.', 'Il passato prossimo si forma con avere o essere al presente + participio passato: ho mangiato, sono arrivato/a. Molti verbi transitivi usano avere; molti verbi di movimento/cambiamento e i riflessivi usano essere.'], example: ['Ieri ho studiato. · Luca è arrivato.', 'Ieri ho studiato. · Luca è arrivato.'], exercises: [exercise('pp-a1-1', ['Choose the correct form: I ___ mangiato.', 'Scegli la forma corretta: Io ___ mangiato.'], ['ho', 'sono', 'hai'], 0, ['Mangiare normally uses avere: ho mangiato.', 'Mangiare normalmente usa avere: ho mangiato.']), exercise('pp-a1-2', ['Choose the correct form: Maria ___ partita.', 'Scegli la forma corretta: Maria ___ partita.'], ['ha', 'è', 'sono'], 1, ['Partire uses essere: Maria è partita.', 'Partire usa essere: Maria è partita.']), exercise('pp-a1-3', ['What is the past participle of parlare?', 'Qual è il participio passato di parlare?'], ['parlato', 'parlito', 'parlato/a'], 0, ['Regular -are verbs form the participle in -ato.', 'I verbi regolari in -are formano il participio in -ato.']), exercise('pp-a1-4', ['Complete: Noi ___ guardato un film ieri.', 'Completa: Noi ___ guardato un film ieri.'], ['abbiamo', 'siamo', 'hanno'], 0, ['Guardare takes avere: noi abbiamo guardato.', 'Guardare usa avere: noi abbiamo guardato.']), exercise('pp-a1-5', ['Luca e Marco ___ arrivati alle otto.', 'Luca e Marco ___ arrivati alle otto.'], ['sono', 'hanno', 'è'], 0, ['Arrivare takes essere; a masculine plural subject uses sono arrivati.', 'Arrivare usa essere; con un soggetto maschile plurale si dice sono arrivati.']), exercise('pp-a1-6', ['What is the past participle of ricevere?', 'Qual è il participio passato di ricevere?'], ['ricevuto', 'riceviuto', 'riceviato'], 0, ['Regular -ere verbs commonly form the participle in -uto: ricevere → ricevuto.', 'I verbi regolari in -ere formano spesso il participio in -uto: ricevere → ricevuto.']), exercise('pp-a1-7', ['Choose the auxiliary: Io ___ corso al parco.', 'Scegli l’ausiliare: Io ___ corso al parco.'], ['sono', 'ho', 'hai'], 0, ['Correre toward a destination uses essere: sono corso.', 'Correre verso una destinazione usa essere: sono corso.']), exercise('pp-a1-8', ['Past participle of vivere?', 'Participio passato di vivere?'], ['vivuto', 'vissuto', 'vivato'], 1, ['Vivere has the irregular participle vissuto.', 'Vivere ha il participio irregolare vissuto.']), exercise('pp-a1-9', ['Choose the auxiliary: Loro ___ saltato la colazione.', 'Scegli l’ausiliare: Loro ___ saltato la colazione.'], ['sono', 'hanno', 'è'], 1, ['Saltare with a direct object (la colazione) uses avere: hanno saltato.', 'Saltare con un complemento oggetto (la colazione) usa avere: hanno saltato.']), exercise('pp-a1-10', ['Past participle of scendere?', 'Participio passato di scendere?'], ['sceso', 'scenduto', 'scendato'], 0, ['Scendere has the irregular participle sceso.', 'Scendere ha il participio irregolare sceso.']), exercise('pp-a1-11', ['Complete: Anna ___ salita in autobus.', 'Completa: Anna ___ salita in autobus.'], ['ha', 'è', 'sono'], 1, ['Salire (to get on) uses essere: è salita.', 'Salire usa essere: è salita.'])] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Regular and irregular participles; agreement with essere.', 'Participi regolari e irregolari; accordo con essere.'], explanation: ['With essere, the participle agrees with the subject: Marco è andato; Anna è andata; Anna e Sara sono andate. Learn common irregular forms such as fatto, visto, preso, scritto and letto.', 'Con essere, il participio concorda con il soggetto: Marco è andato; Anna è andata; Anna e Sara sono andate. Impara forme irregolari comuni come fatto, visto, preso, scritto e letto.'], example: ['Le ragazze sono uscite; abbiamo fatto i compiti.', 'Le ragazze sono uscite; abbiamo fatto i compiti.'], exercises: [exercise('pp-a2-1', ['Anna and Lucia ___ arrivate.', 'Anna e Lucia ___ arrivate.'], ['sono', 'hanno', 'è'], 0, ['Essere is used and the feminine plural participle is arrivate.', 'Si usa essere e il participio femminile plurale è arrivate.']), exercise('pp-a2-2', ['Choose the irregular past participle: fare.', 'Scegli il participio passato irregolare di fare.'], ['facito', 'fatto', 'fato'], 1, ['Fare has the irregular participle fatto.', 'Fare ha il participio irregolare fatto.']), exercise('pp-a2-3', ['Complete: Ieri noi ___ un film.', 'Completa: Ieri noi ___ un film.'], ['siamo visto', 'abbiamo visto', 'abbiamo visti'], 1, ['Vedere takes avere; with a normal preceding object, the participle is visto.', 'Vedere usa avere; con un complemento oggetto normale il participio è visto.']), exercise('pp-a2-4', ['Choose the irregular past participle of scrivere.', 'Scegli il participio passato irregolare di scrivere.'], ['scrivuto', 'scritto', 'scrivato'], 1, ['Scrivere has the irregular past participle scritto.', 'Scrivere ha il participio passato irregolare scritto.']), exercise('pp-a2-5', ['Marco e Luca sono ___ a casa.', 'Marco e Luca sono ___ a casa.'], ['tornato', 'tornati', 'tornate'], 1, ['The masculine plural subject requires tornati.', 'Il soggetto maschile plurale richiede tornati.']), exercise('pp-a2-6', ['Ieri Anna ha ___ una lettera.', 'Ieri Anna ha ___ una lettera.'], ['scritta', 'scritto', 'scritti'], 1, ['With avere and the direct object after the verb, the past participle normally stays unchanged: ha scritto una lettera.', 'Con avere e il complemento oggetto dopo il verbo, il participio normalmente resta invariato: ha scritto una lettera.']), exercise('pp-a2-7', ['Le ragazze sono ___ dal treno.', 'Le ragazze sono ___ dal treno.'], ['sceso', 'scese', 'scesi'], 1, ['With essere and a feminine plural subject the participle is scese.', 'Con essere e un soggetto femminile plurale il participio è scese.']), exercise('pp-a2-8', ['Choose the correct sentence (activity of running).', 'Scegli la frase corretta (attività del correre).'], ['Ho corso per un’ora.', 'Sono corso per un’ora al parco ieri destinazione.', 'Ho corsa per un’ora.'], 0, ['Running as an activity (for an hour) uses avere: ho corso.', 'Correre come attività (per un’ora) usa avere: ho corso.']), exercise('pp-a2-9', ['Past participle of trascorrere?', 'Participio passato di trascorrere?'], ['trascorruto', 'trascorso', 'trascorrato'], 1, ['Trascorrere follows correre: trascorso.', 'Trascorrere segue correre: trascorso.']), exercise('pp-a2-10', ['Complete: I prezzi sono ___ molto.', 'Completa: I prezzi sono ___ molto.'], ['saliti', 'salito', 'salite'], 0, ['Masculine plural subject i prezzi with essere: saliti.', 'Soggetto maschile plurale i prezzi con essere: saliti.']), exercise('pp-a2-11', ['Choose the irregular participle of prendere.', 'Scegli il participio irregolare di prendere.'], ['prenduto', 'preso', 'prendato'], 1, ['Prendere has the irregular participle preso.', 'Prendere ha il participio irregolare preso.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Build accurate past narratives and handle pronoun agreement.', 'Costruisci racconti al passato e gestisci l’accordo con i pronomi.'], explanation: ['At B1, combine auxiliaries, irregular participles, subject agreement with essere, and direct object pronouns: Le ho viste (the feminine plural “them”).', 'Al livello B1 combina ausiliari, participi irregolari, accordo del soggetto con essere e pronomi diretti: Le ho viste (riferito a “loro” femminile plurale).'], example: ['Ieri sono uscita presto, ho preso il treno e ho incontrato le mie amiche: le ho viste in centro.', 'Ieri sono uscita presto, ho preso il treno e ho incontrato le mie amiche: le ho viste in centro.'], exercises: [exercise('pp-b1-1', ['Choose the correct sentence (speaker is female).', 'Scegli la frase corretta (chi parla è una donna).'], ['Ieri sono andato a scuola.', 'Ieri ho andata a scuola.', 'Ieri sono andata a scuola.'], 2, ['Andare uses essere; the feminine speaker requires andata.', 'Andare usa essere; una parlante richiede andata.']), exercise('pp-b1-2', ['Replace “le fotografie”: Ho visto le fotografie.', 'Sostituisci “le fotografie”: Ho visto le fotografie.'], ['Le ho viste.', 'Le ho visto.', 'Gli ho viste.'], 0, ['With a preceding direct object pronoun, the participle agrees: le fotografie → le ho viste.', 'Con un pronome diretto prima del verbo, il participio concorda: le fotografie → le ho viste.']), exercise('pp-b1-3', ['Choose the correct sequence.', 'Scegli la sequenza corretta.'], ['Siamo arrivati, poi abbiamo cenato.', 'Abbiamo arrivati, poi siamo cenati.', 'Siamo arrivato, poi abbiamo cenato.'], 0, ['Arrivare uses essere (plural subject: arrivati); cenare uses avere: abbiamo cenato.', 'Arrivare usa essere (soggetto plurale: arrivati); cenare usa avere: abbiamo cenato.']), exercise('pp-b1-4', ['Choose the sentence that matches “She spent the holidays at the sea.”', 'Scegli la frase per “Ha trascorso le vacanze al mare.”'], ['Ha trascorso le vacanze al mare.', 'È trascorsa le vacanze al mare.', 'Ha trascorsa le vacanze al mare.'], 0, ['Trascorrere with a direct object uses avere and the participle stays trascorso.', 'Trascorrere con un complemento oggetto usa avere e il participio resta trascorso.']), exercise('pp-b1-5', ['Replace “le scale”: Maria ha sceso le scale. → ', 'Sostituisci “le scale”: Maria ha sceso le scale. →'], ['Le ha scese.', 'Le ha sceso.', 'Ne ha scese.'], 0, ['With a preceding feminine plural pronoun, the participle agrees: le ha scese.', 'Con il pronome femminile plurale prima del verbo, il participio concorda: le ha scese.'])] }
    }
  },
  {
    id: 'partitive', title: { en: 'Partitive articles · Articolo partitivo', it: 'Articolo partitivo', pt: 'Artigos partitivos · Articolo partitivo', es: 'Artículos partitivos · Articolo partitivo', fr: 'Articles partitifs · Articolo partitivo', de: 'Teilungsartikel · Articolo partitivo' }, subtitle: { en: 'Express an unspecified amount: some / any.', it: 'Esprimi una quantità non precisa: some / any.', pt: 'Expresse uma quantidade indefinida: algum / um pouco de.', es: 'Expresa una cantidad indefinida: algo de / algún.', fr: 'Exprime une quantité indéterminée : du / des.', de: 'Drücke eine unbestimmte Menge aus: etwas / einige.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Recognise del, della, dell’ and plural forms.', 'Riconosci del, della, dell’ e le forme plurali.'], explanation: ['The partitive article means “some” or an unspecified amount. It combines di + a definite article: del pane, della pasta, dell’acqua, dei biscotti, degli spaghetti, delle mele.', 'L’articolo partitivo indica una quantità non precisa. Unisce di + articolo determinativo: del pane, della pasta, dell’acqua, dei biscotti, degli spaghetti, delle mele.'], example: ['Vorrei del pane e delle mele.', 'Vorrei del pane e delle mele.'], exercises: [exercise('part-a1-1', ['Complete: Vorrei ___ acqua.', 'Completa: Vorrei ___ acqua.'], ['del', 'dell’', 'della'], 1, ['Acqua is feminine singular and begins with a vowel: dell’acqua.', 'Acqua è femminile singolare e inizia per vocale: dell’acqua.']), exercise('part-a1-2', ['Complete: Compro ___ mele.', 'Completa: Compro ___ mele.'], ['dei', 'delle', 'degli'], 1, ['Mele is feminine plural: delle mele.', 'Mele è femminile plurale: delle mele.']), exercise('part-a1-3', ['Complete: Mangio ___ pane.', 'Completa: Mangio ___ pane.'], ['del', 'della', 'delle'], 0, ['Pane is masculine singular: del pane.', 'Pane è maschile singolare: del pane.']), exercise('part-a1-4', ['Complete: Vorrei ___ formaggio.', 'Completa: Vorrei ___ formaggio.'], ['del', 'della', 'delle'], 0, ['Formaggio is masculine singular: del formaggio.', 'Formaggio è maschile singolare: del formaggio.']), exercise('part-a1-5', ['Complete: Compro ___ pasta fresca.', 'Completa: Compro ___ pasta fresca.'], ['della', 'del', 'degli'], 0, ['Pasta is feminine singular: della pasta.', 'Pasta è femminile singolare: della pasta.']), exercise('part-a1-6', ['Complete: Mangio ___ biscotti.', 'Completa: Mangio ___ biscotti.'], ['dei', 'degli', 'delle'], 0, ['Biscotti is masculine plural with a regular consonant: dei biscotti.', 'Biscotti è maschile plurale e inizia con una consonante semplice: dei biscotti.']), exercise('part-a1-7', ['Complete: Vorrei ___ zucchero.', 'Completa: Vorrei ___ zucchero.'], ['del', 'dello', 'della'], 1, ['Zucchero begins with z: dello zucchero.', 'Zucchero inizia per z: dello zucchero.']), exercise('part-a1-8', ['Complete: Compro ___ arance.', 'Completa: Compro ___ arance.'], ['delle', 'dei', 'degli'], 0, ['Arance is feminine plural: delle arance.', 'Arance è femminile plurale: delle arance.']), exercise('part-a1-9', ['Complete: Mangio ___ prosciutto.', 'Completa: Mangio ___ prosciutto.'], ['del', 'della', 'dei'], 0, ['Prosciutto is masculine singular: del prosciutto.', 'Prosciutto è maschile singolare: del prosciutto.']), exercise('part-a1-10', ['Complete: Bevo ___ latte.', 'Completa: Bevo ___ latte.'], ['del', 'dello', 'della'], 0, ['Latte is masculine singular with a regular consonant: del latte.', 'Latte è maschile singolare con consonante semplice: del latte.']), exercise('part-a1-11', ['Complete: Ci sono ___ studenti in aula.', 'Completa: Ci sono ___ studenti in aula.'], ['dei', 'degli', 'delle'], 1, ['Studenti begins with s + consonant: degli studenti.', 'Studenti inizia con s + consonante: degli studenti.'])] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Select forms by gender and sound; use in shopping and food contexts.', 'Scegli le forme in base a genere e suono; usale al mercato e a tavola.'], explanation: ['Use dello before masculine singular nouns beginning with s + consonant or z (dello zucchero); degli for the corresponding plural (degli zaini). The partitive is common when ordering or shopping.', 'Si usa dello davanti a nomi maschili singolari che iniziano con s + consonante o z (dello zucchero); degli al plurale (degli zaini). Il partitivo è comune quando si ordina o si fa la spesa.'], example: ['Al mercato prendo dello zucchero, degli spinaci e delle pere.', 'Al mercato prendo dello zucchero, degli spinaci e delle pere.'], exercises: [exercise('part-a2-1', ['Complete: Metto ___ zucchero nel caffè.', 'Completa: Metto ___ zucchero nel caffè.'], ['del', 'dello', 'della'], 1, ['Zucchero begins with z, so use dello.', 'Zucchero inizia per z, quindi si usa dello.']), exercise('part-a2-2', ['Complete: Abbiamo comprato ___ yogurt.', 'Completa: Abbiamo comprato ___ yogurt.'], ['dello', 'della', 'delle'], 0, ['Yogurt is treated as masculine; dello is the standard partitive form before this sound.', 'Yogurt è trattato come maschile; dello è la forma partitiva usata davanti a questo suono.']), exercise('part-a2-3', ['Choose the correct phrase.', 'Scegli il gruppo corretto.'], ['degli amici', 'dei amici', 'delle amici'], 0, ['Amici is masculine plural beginning with a vowel: degli amici.', 'Amici è maschile plurale e inizia per vocale: degli amici.']), exercise('part-a2-4', ['Complete both forms: Aggiungo ___ olio e ___ zucchero.', 'Completa entrambe le forme: Aggiungo ___ olio e ___ zucchero.'], ['dell’ / dello', 'del / dello', 'dello / dell’'], 0, ['Olio begins with a vowel: dell’olio. Zucchero begins with z: dello zucchero.', 'Olio inizia per vocale: dell’olio. Zucchero inizia per z: dello zucchero.']), exercise('part-a2-5', ['At the market I buy ___ spinach and ___ pears.', 'Al mercato compro ___ spinaci e ___ pere.'], ['degli / delle', 'dei / degli', 'delle / degli'], 0, ['Spinaci is masculine plural with s + consonant: degli; pere is feminine plural: delle.', 'Spinaci è maschile plurale con s + consonante: degli; pere è femminile plurale: delle.']), exercise('part-a2-6', ['Choose the correct partitive: Vuoi ___ formaggio sulla pasta?', 'Scegli il partitivo corretto: Vuoi ___ formaggio sulla pasta?'], ['del', 'dello', 'della'], 0, ['Formaggio is masculine singular and begins with a regular consonant: del formaggio.', 'Formaggio è maschile singolare e inizia con una consonante semplice: del formaggio.']), exercise('part-a2-7', ['Which word means roughly the same as “dei libri”?', 'Quale espressione equivale a “dei libri”?'], ['alcuni libri', 'qualche libri', 'un po’ di libri'], 0, ['Alcuni + plural noun means “some”: alcuni libri.', 'Alcuni + nome plurale significa “some”: alcuni libri.']), exercise('part-a2-8', ['Choose the correct form with “qualche”.', 'Scegli la forma corretta con “qualche”.'], ['qualche amico', 'qualche amici', 'qualche degli amici'], 0, ['Qualche always takes a singular noun: qualche amico.', 'Qualche richiede sempre un nome singolare: qualche amico.']), exercise('part-a2-9', ['Complete: Metto ___ olio nell’insalata.', 'Completa: Metto ___ olio nell’insalata.'], ['dell’', 'del', 'dello'], 0, ['Olio begins with a vowel: dell’olio.', 'Olio inizia per vocale: dell’olio.']), exercise('part-a2-10', ['In a negative sentence, which is most natural?', 'In una frase negativa, qual è più naturale?'], ['Non ho pane.', 'Non ho del pane.', 'Non ho dello pane.'], 0, ['The partitive is usually dropped in negatives: non ho pane.', 'Il partitivo di solito si omette al negativo: non ho pane.']), exercise('part-a2-11', ['Complete: Al bar prendo ___ cornetti.', 'Completa: Al bar prendo ___ cornetti.'], ['dei', 'degli', 'delle'], 0, ['Cornetti is masculine plural with a regular consonant: dei cornetti.', 'Cornetti è maschile plurale con consonante semplice: dei cornetti.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Distinguish partitive articles from articulated prepositions.', 'Distingui gli articoli partitivi dalle preposizioni articolate.'], explanation: ['Context determines the function. Ho comprato del pane = some bread (partitive). Il colore del pane = the colour of the bread (di + article, possession/specification).', 'Il contesto determina la funzione. Ho comprato del pane = una quantità di pane (partitivo). Il colore del pane = il colore che appartiene al pane (di + articolo, specificazione).'], example: ['Bevo dell’acqua (some water); il sapore dell’acqua (the taste of the water).', 'Bevo dell’acqua (un po’ d’acqua); il sapore dell’acqua (il sapore che ha l’acqua).'], exercises: [exercise('part-b1-1', ['In “Il profumo del caffè è intenso”, what is “del”?', 'Nella frase “Il profumo del caffè è intenso”, che funzione ha “del”?'], ['Partitive article: some coffee', 'Articulated preposition: of the coffee', 'Definite article'], 1, ['It expresses a relationship/specification: the smell of the coffee, not some coffee.', 'Esprime una specificazione: il profumo che appartiene al caffè, non una quantità di caffè.']), exercise('part-b1-2', ['Choose the sentence expressing an unspecified quantity.', 'Scegli la frase che esprime una quantità non precisa.'], ['Il prezzo del pane aumenta.', 'Vorrei del pane, per favore.', 'La crosta del pane è croccante.'], 1, ['Vorrei del pane means “I would like some bread”: del is partitive.', 'Vorrei del pane significa “I would like some bread”: del è partitivo.']), exercise('part-b1-3', ['Complete naturally: Per la ricetta servono ___ spinaci.', 'Completa in modo naturale: Per la ricetta servono ___ spinaci.'], ['degli', 'delle', 'del'], 0, ['Spinaci is masculine plural with s + consonant: degli spinaci.', 'Spinaci è maschile plurale con s + consonante: degli spinaci.']), exercise('part-b1-4', ['In “La porta della casa è aperta”, what is “della”?', 'Nella frase “La porta della casa è aperta”, che cos’è “della”?'], ['Partitive article: some house', 'Articulated preposition: of the house', 'Indefinite article'], 1, ['It specifies possession: the door of the house, not some house.', 'Indica specificazione: la porta che appartiene alla casa, non una quantità.']), exercise('part-b1-5', ['Rewrite with “ne”: Ho comprato dei biscotti. → ', 'Riscrivi con “ne”: Ho comprato dei biscotti. →'], ['Ne ho comprati.', 'Li ho comprati tutti.', 'Ne ho comprato.'], 0, ['Ne replaces the partitive and the participle agrees: ne ho comprati.', 'Ne sostituisce il partitivo e il participio concorda: ne ho comprati.'])] }
    }
  },
  {
    id: 'reflexive', title: { en: 'Reflexive verbs · Verbi riflessivi', it: 'Verbi riflessivi', pt: 'Verbos reflexivos · Verbi riflessivi', es: 'Verbos reflexivos · Verbi riflessivi', fr: 'Verbes pronominaux · Verbi riflessivi', de: 'Reflexive Verben · Verbi riflessivi' }, subtitle: { en: 'Describe routines and actions done to oneself.', it: 'Descrivi le abitudini e le azioni che si compiono su sé stessi.', pt: 'Descreva rotinas e ações feitas sobre si mesmo.', es: 'Describe rutinas y acciones hechas sobre uno mismo.', fr: 'Décris des routines et des actions faites sur soi-même.', de: 'Beschreibe Routinen und Handlungen an sich selbst.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Reflexive pronouns and daily routine verbs in the present.', 'Pronomi riflessivi e verbi della routine al presente.'], explanation: ['A reflexive verb uses a pronoun that refers back to the subject: mi, ti, si, ci, vi, si. Examples: mi sveglio, ti lavi, si veste. The infinitive ends in -si.', 'Un verbo riflessivo usa un pronome che si riferisce al soggetto: mi, ti, si, ci, vi, si. Esempi: mi sveglio, ti lavi, si veste. L’infinito termina in -si.'], example: ['Mi sveglio alle sette e mi lavo.', 'Mi sveglio alle sette e mi lavo.'], exercises: [exercise('ref-a1-1', ['Complete: Io ___ sveglio alle sette.', 'Completa: Io ___ sveglio alle sette.'], ['mi', 'ti', 'si'], 0, ['With io, the reflexive pronoun is mi.', 'Con io, il pronome riflessivo è mi.']), exercise('ref-a1-2', ['Complete: Tu ___ lavi.', 'Completa: Tu ___ lavi.'], ['si', 'ti', 'ci'], 1, ['With tu, use ti: tu ti lavi.', 'Con tu si usa ti: tu ti lavi.']), exercise('ref-a1-3', ['Choose the correct present tense.', 'Scegli il presente corretto.'], ['Lei si veste.', 'Lei ti veste.', 'Lei mi vesto.'], 0, ['Lei uses si and the third-person verb form: si veste.', 'Con lei si usa si e la terza persona del verbo: si veste.']), exercise('ref-a1-4', ['Complete: Loro ___ preparano per la scuola.', 'Completa: Loro ___ preparano per la scuola.'], ['si', 'ci', 'vi'], 0, ['With loro, the reflexive pronoun is si: loro si preparano.', 'Con loro, il pronome riflessivo è si: loro si preparano.']), exercise('ref-a1-5', ['Complete: Noi ___ addormentiamo presto.', 'Completa: Noi ___ addormentiamo presto.'], ['ci', 'si', 'ti'], 0, ['With noi, use ci before the verb: ci addormentiamo.', 'Con noi si usa ci prima del verbo: ci addormentiamo.']), exercise('ref-a1-6', ['Choose the correct sentence for tu.', 'Scegli la frase corretta con tu.'], ['Tu ti pettini.', 'Tu si pettini.', 'Tu ti pettina.'], 0, ['Tu takes the pronoun ti and the second-person verb form pettini.', 'Con tu si usa il pronome ti e la seconda persona pettini.']), exercise('ref-a1-7', ['Complete: Voi ___ divertite alla festa.', 'Completa: Voi ___ divertite alla festa.'], ['vi', 'ci', 'si'], 0, ['With voi, the reflexive pronoun is vi.', 'Con voi, il pronome riflessivo è vi.']), exercise('ref-a1-8', ['Choose the correct present: Io ___ chiamo Luca.', 'Scegli il presente corretto: Io ___ chiamo Luca.'], ['mi', 'ti', 'si'], 0, ['Chiamarsi: io mi chiamo.', 'Chiamarsi: io mi chiamo.']), exercise('ref-a1-9', ['Complete: Lei ___ trucca ogni mattina.', 'Completa: Lei ___ trucca ogni mattina.'], ['mi', 'si', 'ti'], 1, ['With lei, the reflexive pronoun is si.', 'Con lei, il pronome riflessivo è si.']), exercise('ref-a1-10', ['Choose the infinitive that is reflexive.', 'Scegli l’infinito che è riflessivo.'], ['alzarsi', 'alzare', 'alzato'], 0, ['A reflexive infinitive ends in -si: alzarsi.', 'Un infinito riflessivo termina in -si: alzarsi.']), exercise('ref-a1-11', ['Complete: Noi ___ riposiamo la domenica.', 'Completa: Noi ___ riposiamo la domenica.'], ['ci', 'vi', 'si'], 0, ['With noi, the reflexive pronoun is ci.', 'Con noi, il pronome riflessivo è ci.'])] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Use reflexive verbs in a complete daily routine and in passato prossimo.', 'Usa i riflessivi nella routine e al passato prossimo.'], explanation: ['Reflexive verbs use essere in the passato prossimo. The participle agrees with the subject: mi sono svegliato/a; ci siamo vestiti/e. Place the reflexive pronoun before the auxiliary.', 'I verbi riflessivi usano essere al passato prossimo. Il participio concorda con il soggetto: mi sono svegliato/a; ci siamo vestiti/e. Il pronome riflessivo precede l’ausiliare.'], example: ['Stamattina mi sono alzata, mi sono vestita e sono uscita.', 'Stamattina mi sono alzata, mi sono vestita e sono uscita.'], exercises: [exercise('ref-a2-1', ['Complete: Ieri Marco ___ è svegliato presto.', 'Completa: Ieri Marco ___ è svegliato presto.'], ['si', 'mi', 'ti'], 0, ['Marco is third person singular: si è svegliato.', 'Marco è terza persona singolare: si è svegliato.']), exercise('ref-a2-2', ['A female speaker says: “I got dressed.”', 'Una donna dice: “Mi sono vestita.”'], ['Mi sono vestito.', 'Mi sono vestita.', 'Ho vestita.'], 1, ['With essere, the participle agrees with the feminine speaker: vestita.', 'Con essere il participio concorda con chi parla: vestita.']), exercise('ref-a2-3', ['Complete: Noi ___ siamo lavati dopo lo sport.', 'Completa: Noi ___ siamo lavati dopo lo sport.'], ['ci', 'vi', 'si'], 0, ['With noi, the reflexive pronoun is ci.', 'Con noi, il pronome riflessivo è ci.']), exercise('ref-a2-4', ['Complete: Ieri Giulia ___ è alzata alle sei.', 'Completa: Ieri Giulia ___ è alzata alle sei.'], ['si', 'mi', 'ci'], 0, ['Giulia is third-person singular, so use si è alzata.', 'Giulia è terza persona singolare, quindi si usa si è alzata.']), exercise('ref-a2-5', ['Paolo e Anna si sono ___ presto.', 'Paolo e Anna si sono ___ presto.'], ['svegliato', 'svegliati', 'svegliate'], 1, ['A mixed-gender plural subject takes the masculine plural participle svegliati.', 'Un soggetto plurale misto richiede il participio maschile plurale svegliati.']), exercise('ref-a2-6', ['Complete: Io ___ sono preparato/a in dieci minuti.', 'Completa: Io ___ sono preparato/a in dieci minuti.'], ['mi', 'ci', 'si'], 0, ['With io, the reflexive pronoun is mi, placed before the auxiliary sono.', 'Con io, il pronome riflessivo è mi e precede l’ausiliare sono.']), exercise('ref-a2-7', ['A female speaker: “I got up early.”', 'Una donna: “Mi sono alzata presto.”'], ['Mi sono alzato presto.', 'Mi sono alzata presto.', 'Ho alzata presto.'], 1, ['Reflexives use essere; the feminine participle is alzata.', 'I riflessivi usano essere; il participio femminile è alzata.']), exercise('ref-a2-8', ['Le ragazze si sono ___ bene.', 'Le ragazze si sono ___ bene.'], ['divertito', 'divertite', 'divertiti'], 1, ['Feminine plural subject: divertite.', 'Soggetto femminile plurale: divertite.']), exercise('ref-a2-9', ['Complete: Tu ___ sei svegliato tardi?', 'Completa: Tu ___ sei svegliato tardi?'], ['ti', 'mi', 'si'], 0, ['With tu, the reflexive pronoun is ti.', 'Con tu, il pronome riflessivo è ti.']), exercise('ref-a2-10', ['Choose the correct auxiliary for a reflexive verb.', 'Scegli l’ausiliare corretto per un verbo riflessivo.'], ['Mi sono lavato.', 'Mi ho lavato.', 'Ho mi lavato.'], 0, ['Reflexive verbs always take essere: mi sono lavato.', 'I verbi riflessivi usano sempre essere: mi sono lavato.']), exercise('ref-a2-11', ['Paolo e Marco si sono ___ alle sette.', 'Paolo e Marco si sono ___ alle sette.'], ['alzato', 'alzati', 'alzate'], 1, ['Masculine plural subject: alzati.', 'Soggetto maschile plurale: alzati.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Build a coherent routine narrative and avoid confusing reflexive/non-reflexive forms.', 'Costruisci un racconto coerente della routine e distingui forme riflessive e non riflessive.'], explanation: ['Some verbs can be reflexive or non-reflexive with a change in meaning: lavarsi (wash oneself) vs lavare la macchina (wash the car). In a narrative, keep the pronoun, auxiliary and participle consistent.', 'Alcuni verbi possono essere riflessivi o non riflessivi con un cambio di significato: lavarsi (lavare sé stessi) e lavare la macchina. In un racconto mantieni coerenti pronome, ausiliare e participio.'], example: ['Dopo che mi sono svegliato, ho preparato il caffè e poi mi sono vestito.', 'Dopo che mi sono svegliato, ho preparato il caffè e poi mi sono vestito.'], exercises: [exercise('ref-b1-1', ['Choose the correct sentence (speaker is female).', 'Scegli la frase corretta (chi parla è una donna).'], ['Mi ho svegliata presto.', 'Mi sono svegliata presto.', 'Sono svegliato presto.'], 1, ['Reflexive verbs use essere; the feminine participle is svegliata.', 'I verbi riflessivi usano essere; il participio femminile è svegliata.']), exercise('ref-b1-2', ['Which sentence means “I washed the car”?', 'Quale frase significa “I washed the car”?'], ['Mi sono lavato la macchina.', 'Ho lavato la macchina.', 'Mi ho lavato.'], 1, ['The car is the object; this is not a reflexive action, so lavare uses avere.', 'La macchina è il complemento oggetto: l’azione non è riflessiva, quindi lavare usa avere.']), exercise('ref-b1-3', ['Choose the correct sequence for “we got up and got dressed”.', 'Scegli la sequenza corretta per “ci siamo alzati e vestiti”.'], ['Ci siamo alzati e ci siamo vestiti.', 'Abbiamo alzati e vestiti.', 'Ci abbiamo alzato e vestito.'], 0, ['Both reflexive verbs use essere and the plural masculine participle here.', 'Entrambi i verbi riflessivi usano essere e qui il participio maschile plurale.']), exercise('ref-b1-4', ['Which means “I washed my hands”?', 'Quale significa “Mi sono lavato le mani”?'], ['Mi sono lavato le mani.', 'Ho lavato le mani mie.', 'Mi ho lavato le mani.'], 0, ['With a body part, use the reflexive + article: mi sono lavato le mani.', 'Con una parte del corpo si usa il riflessivo + articolo: mi sono lavato le mani.']), exercise('ref-b1-5', ['Choose the consistent narrative (female speaker).', 'Scegli il racconto coerente (parlante donna).'], ['Mi sono svegliata, mi sono vestita e sono uscita.', 'Mi ho svegliata, mi sono vestito e sono uscito.', 'Sono svegliata, ho vestita e uscita.'], 0, ['All reflexive/movement verbs use essere with feminine agreement.', 'Tutti i verbi riflessivi e di movimento usano essere con accordo femminile.'])] }
    }
  },
  {
    id: 'sentence-building', title: { en: 'Sentence construction · Costruzione delle frasi', it: 'Costruzione delle frasi', pt: 'Construção de frases · Costruzione delle frasi', es: 'Construcción de frases · Costruzione delle frasi', fr: 'Construction de phrases · Costruzione delle frasi', de: 'Satzbau · Costruzione delle frasi' }, subtitle: { en: 'Put grammar together to communicate clearly.', it: 'Unisci le regole grammaticali per comunicare con chiarezza.', pt: 'Junte a gramática para se comunicar com clareza.', es: 'Combina la gramática para comunicarte con claridad.', fr: 'Assemble la grammaire pour communiquer clairement.', de: 'Füge die Grammatik zusammen, um dich klar auszudrücken.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Basic subject + verb + object order.', 'Ordine base soggetto + verbo + complemento.'], explanation: ['A simple Italian sentence often follows subject + verb + object. Articles and adjectives agree with the noun: La ragazza compra una mela rossa. Subject pronouns can be omitted when clear.', 'Una frase semplice italiana segue spesso soggetto + verbo + complemento. Articoli e aggettivi concordano con il nome: La ragazza compra una mela rossa. I pronomi soggetto si possono omettere quando sono chiari.'], example: ['(Io) studio italiano ogni giorno.', '(Io) studio italiano ogni giorno.'], exercises: [exercise('sent-a1-1', ['Choose the correct word order.', 'Scegli l’ordine corretto delle parole.'], ['La ragazza legge un libro.', 'La ragazza un libro legge.', 'Legge la un libro ragazza.'], 0, ['The natural neutral order is subject + verb + object.', 'L’ordine neutro naturale è soggetto + verbo + complemento.']), exercise('sent-a1-2', ['Complete the sentence with the correct article.', 'Completa la frase con l’articolo corretto.'], ['Una', 'Un', 'Uno'], 0, ['Ragazza is feminine singular: una ragazza.', 'Ragazza è femminile singolare: una ragazza.'], '___ ragazza studia'), exercise('sent-a1-3', ['Choose the correct adjective agreement.', 'Scegli l’accordo corretto dell’aggettivo.'], ['una casa grande', 'una casa grandi', 'un casa grande'], 0, ['Casa is feminine singular; grande agrees in number and is invariable for gender in this form.', 'Casa è femminile singolare; grande concorda nel numero e in questa forma non cambia per genere.']), exercise('sent-a1-4', ['Choose the natural sentence order.', 'Scegli l’ordine naturale della frase.'], ['Dopo la scuola, Marco gioca a calcio.', 'Dopo la scuola, gioca Marco a calcio.', 'Dopo scuola Marco a calcio gioca.'], 0, ['A time expression can begin the sentence, followed by subject + verb + complement.', 'Un’espressione di tempo può aprire la frase, seguita da soggetto + verbo + complemento.']), exercise('sent-a1-5', ['Complete: Le ragazze ___ molto simpatiche.', 'Completa: Le ragazze ___ molto simpatiche.'], ['sono', 'è', 'siamo'], 0, ['Le ragazze is third-person feminine plural, so use sono.', 'Le ragazze è femminile plurale, quindi si usa sono.']), exercise('sent-a1-6', ['Choose the correctly formed sentence.', 'Scegli la frase formata correttamente.'], ['Ogni sera leggo un libro prima di dormire.', 'Ogni sera un libro leggo prima dormire.', 'Ogni sera leggo prima un libro di dormire.'], 0, ['The sentence uses a natural time expression + verb + object + time clause order.', 'La frase usa un ordine naturale: espressione di tempo + verbo + complemento + proposizione temporale.']), exercise('sent-a1-7', ['Choose the correct word order.', 'Scegli l’ordine corretto.'], ['Il bambino beve il latte.', 'Il bambino il latte beve.', 'Beve il bambino latte il.'], 0, ['Neutral order is subject + verb + object.', 'L’ordine neutro è soggetto + verbo + complemento.']), exercise('sent-a1-8', ['Complete with the correct verb: Io ___ a casa.', 'Completa con il verbo corretto: Io ___ a casa.'], ['sono', 'è', 'siamo'], 0, ['Io takes sono: io sono a casa.', 'Io richiede sono: io sono a casa.'], 'Io ___ a casa'), exercise('sent-a1-9', ['Choose the correct agreement.', 'Scegli l’accordo corretto.'], ['un libro rosso', 'un libro rossa', 'una libro rosso'], 0, ['Libro is masculine singular: un libro rosso.', 'Libro è maschile singolare: un libro rosso.']), exercise('sent-a1-10', ['Choose the natural sentence.', 'Scegli la frase naturale.'], ['Ogni mattina bevo un caffè.', 'Ogni mattina un caffè bevo.', 'Bevo ogni un caffè mattina.'], 0, ['A time phrase can open the sentence, then verb + object.', 'Un’espressione di tempo può aprire la frase, poi verbo + complemento.']), exercise('sent-a1-11', ['Complete: I bambini ___ nel parco.', 'Completa: I bambini ___ nel parco.'], ['giocano', 'gioca', 'giochiamo'], 0, ['I bambini is third-person plural: giocano.', 'I bambini è terza persona plurale: giocano.'], 'I bambini ___ nel parco')] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Combine articles, adjectives, pronouns and past tense.', 'Combina articoli, aggettivi, pronomi e passato.'], explanation: ['Build longer sentences by checking each agreement and keeping pronouns close to the verb: Ieri ho comprato le mele rosse e le ho messe sul tavolo.', 'Costruisci frasi più lunghe controllando ogni accordo e tenendo i pronomi vicino al verbo: Ieri ho comprato le mele rosse e le ho messe sul tavolo.'], example: ['Ieri ho comprato delle mele e le ho messe in frigorifero.', 'Ieri ho comprato delle mele e le ho messe in frigorifero.'], exercises: [exercise('sent-a2-1', ['Choose the complete correct sentence.', 'Scegli la frase completa corretta.'], ['Ieri sono andato al mercato e ho comprato delle mele.', 'Ieri ho andato al mercato e sono comprato delle mele.', 'Ieri sono andata al mercato e ho comprato dei mele.'], 0, ['Andare uses essere; comprare uses avere; mele is feminine plural, so delle mele.', 'Andare usa essere; comprare usa avere; mele è femminile plurale, quindi delle mele.']), exercise('sent-a2-2', ['Arrange the idea into a natural sentence by choosing the correct version.', 'Scegli la versione con l’ordine naturale.'], ['La mattina mi sveglio presto e faccio colazione.', 'Mi la mattina sveglio presto e colazione faccio.', 'La mattina sveglio mi presto.'], 0, ['A time expression can begin the sentence; the reflexive pronoun stays before the verb.', 'Un’espressione di tempo può aprire la frase; il pronome riflessivo precede il verbo.']), exercise('sent-a2-3', ['Choose the correct pronoun sentence.', 'Scegli la frase con il pronome corretto.'], ['Vedo le mie amiche: le vedo spesso.', 'Vedo le mie amiche: gli vedo spesso.', 'Vedo le mie amiche: li vedo spesso.'], 0, ['Amiche is feminine plural: le.', 'Amiche è femminile plurale: le.']), exercise('sent-a2-4', ['Choose the correct connected sentence.', 'Scegli la frase collegata corretta.'], ['Ho comprato una torta e l’ho portata a casa.', 'Ho comprato una torta e la ho portato a casa.', 'Ho comprato una torta e gli ho portata a casa.'], 0, ['The direct pronoun l’ replaces la torta; the participle agrees in the feminine: portata.', 'Il pronome diretto l’ sostituisce la torta; il participio concorda al femminile: portata.']), exercise('sent-a2-5', ['Choose the correct sequence of actions.', 'Scegli la sequenza corretta delle azioni.'], ['Dopo la lezione siamo andati al bar e abbiamo preso un caffè.', 'Dopo la lezione siamo andato al bar e abbiamo preso un caffè.', 'Dopo la lezione abbiamo andati al bar e siamo preso un caffè.'], 0, ['Andare takes essere with the plural form and prendere takes avere: siamo andati, abbiamo preso.', 'Andare usa essere al plurale e prendere usa avere: siamo andati, abbiamo preso.']), exercise('sent-a2-6', ['Choose the sentence with the correct connector and word order.', 'Scegli la frase con il connettivo e l’ordine corretti.'], ['Prima ho finito i compiti, poi sono uscito.', 'Poi prima ho finito i compiti, sono uscito.', 'Prima ho finito i compiti, poi ho uscito.'], 0, ['Prima and poi mark a clear sequence; uscire takes essere in the passato prossimo.', 'Prima e poi indicano una sequenza chiara; uscire usa essere al passato prossimo.']), exercise('sent-a2-7', ['Choose the fully correct sentence.', 'Scegli la frase corretta.'], ['Ho visto Anna e l’ho salutata.', 'Ho visto Anna e l’ho salutato.', 'Ho visto Anna e la ho salutata.'], 0, ['Direct pronoun l’ (Anna) + feminine participle salutata.', 'Pronome diretto l’ (Anna) + participio femminile salutata.']), exercise('sent-a2-8', ['Choose the correct connected sentence.', 'Scegli la frase collegata corretta.'], ['Siamo usciti e abbiamo preso un gelato.', 'Abbiamo usciti e siamo preso un gelato.', 'Siamo uscito e abbiamo presa un gelato.'], 0, ['Uscire uses essere (usciti); prendere uses avere (abbiamo preso).', 'Uscire usa essere (usciti); prendere usa avere (abbiamo preso).']), exercise('sent-a2-9', ['Choose the correct pronoun sentence.', 'Scegli la frase con il pronome corretto.'], ['Compro i fiori: li metto sul tavolo.', 'Compro i fiori: le metto sul tavolo.', 'Compro i fiori: lo metto sul tavolo.'], 0, ['I fiori is masculine plural: li.', 'I fiori è maschile plurale: li.']), exercise('sent-a2-10', ['Choose the natural order with a time clause.', 'Scegli l’ordine naturale con una frase temporale.'], ['Quando arrivo a casa, preparo la cena.', 'Preparo la cena quando casa arrivo a.', 'Quando a casa arrivo, cena la preparo.'], 0, ['A quando-clause can open the sentence, then subject-verb-object.', 'Una frase con quando può aprire la frase, poi soggetto-verbo-complemento.']), exercise('sent-a2-11', ['Choose the correct sentence using “ne”.', 'Scegli la frase corretta con “ne”.'], ['Vuoi del pane? Sì, ne prendo un po’.', 'Vuoi del pane? Sì, lo prendo un po’.', 'Vuoi del pane? Sì, la prendo un po’.'], 0, ['Ne replaces the partitive del pane: ne prendo un po’.', 'Ne sostituisce il partitivo del pane: ne prendo un po’.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Combine multiple grammar points in connected, accurate sentences.', 'Combina più elementi grammaticali in frasi collegate e corrette.'], explanation: ['At B1, combine tense, agreement, pronouns and connectors. Review the sentence in layers: verb/auxiliary, subject agreement, article/noun agreement, then pronoun reference and word order.', 'Al livello B1 combina tempi, accordi, pronomi e connettivi. Rivedi la frase a livelli: verbo/ausiliare, accordo del soggetto, accordo articolo/nome, riferimento del pronome e ordine delle parole.'], example: ['Ieri mi sono svegliata presto, ho preparato la colazione e l’ho condivisa con i miei amici.', 'Ieri mi sono svegliata presto, ho preparato la colazione e l’ho condivisa con i miei amici.'], exercises: [exercise('sent-b1-1', ['Choose the fully correct sentence.', 'Scegli la frase completamente corretta.'], ['Ieri mi sono svegliata, ho preparato dei panini e li ho portati al lavoro.', 'Ieri mi ho svegliata, ho preparato dei panini e le ho portate al lavoro.', 'Ieri sono svegliato, ho preparato degli panini e li ho portato al lavoro.'], 0, ['The reflexive uses essere and feminine agreement; dei panini is masculine plural; li ho portati agrees with the preceding pronoun.', 'Il riflessivo usa essere e l’accordo femminile; dei panini è maschile plurale; li ho portati concorda con il pronome precedente.']), exercise('sent-b1-2', ['Correct the error: “Io ho andato a scuola ieri.” Choose the correction.', 'Correggi l’errore: “Io ho andato a scuola ieri.” Scegli la correzione.'], ['Ieri sono andato/a a scuola.', 'Ieri ho andato a scuola.', 'Ieri sono andati a scuola.'], 0, ['Andare takes essere. The participle agrees with the speaker: andato (masculine) or andata (feminine).', 'Andare usa essere. Il participio concorda con chi parla: andato (maschile) o andata (femminile).']), exercise('sent-b1-3', ['Choose the most natural connected sentence.', 'Scegli la frase collegata più naturale.'], ['Quando sono arrivato a casa, mi sono fatto una doccia e poi ho cenato.', 'Quando ho arrivato a casa, mi ho fatto una doccia e poi sono cenato.', 'Quando sono arrivata a casa, mi sono fatto una doccia e poi ho cenato.'], 0, ['Arrivare uses essere; farsi la doccia is reflexive and uses essere; cenare uses avere. The masculine speaker form is consistent.', 'Arrivare usa essere; farsi la doccia è riflessivo e usa essere; cenare usa avere. La forma maschile del parlante è coerente.']), exercise('sent-b1-4', ['Choose the fully correct sentence.', 'Scegli la frase completamente corretta.'], ['Ieri sono andata al mercato, ho comprato delle mele e le ho mangiate.', 'Ieri ho andata al mercato, ho comprato dei mele e li ho mangiato.', 'Ieri sono andato al mercato, ho comprata delle mele e le ho mangiato.'], 0, ['Andare essere + feminine; delle mele; le ho mangiate (agreement with preceding pronoun).', 'Andare essere + femminile; delle mele; le ho mangiate (accordo col pronome precedente).']), exercise('sent-b1-5', ['Combine into one natural sentence.', 'Unisci in una frase naturale.'], ['Mentre tornavo a casa, ho incontrato Sara e l’ho salutata.', 'Mentre sono tornato a casa, incontravo Sara e l’ho salutato.', 'Mentre tornavo a casa, ho incontrata Sara e la ho salutata.'], 0, ['Imperfetto for the background (tornavo), passato prossimo for the event; feminine agreement l’ho salutata.', 'Imperfetto per lo sfondo (tornavo), passato prossimo per l’evento; accordo femminile l’ho salutata.'])] }
    }
  },
  {
    id: 'present-tense', title: { en: 'Present tense · Presente indicativo', it: 'Presente indicativo', pt: 'Presente · Presente indicativo', es: 'Presente · Presente indicativo', fr: 'Présent · Presente indicativo', de: 'Präsens · Presente indicativo' }, subtitle: { en: 'Talk about habits, facts and what is happening now.', it: 'Parla di abitudini, fatti e di ciò che succede ora.', pt: 'Fale de hábitos, fatos e do que acontece agora.', es: 'Habla de hábitos, hechos y de lo que pasa ahora.', fr: 'Parle d’habitudes, de faits et de ce qui se passe maintenant.', de: 'Sprich über Gewohnheiten, Fakten und was gerade passiert.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Regular -are, -ere and -ire verbs; subject endings; essere and avere.', 'Verbi regolari in -are, -ere e -ire; desinenze; essere e avere.'], explanation: ['In the present tense, the verb ending changes with the subject. For regular verbs: parlare → parlo, parli, parla, parliamo, parlate, parlano; prendere → prendo, prendi, prende, prendiamo, prendete, prendono; dormire → dormo, dormi, dorme, dormiamo, dormite, dormono. Essere and avere are irregular: sono/sei/è… and ho/hai/ha…', 'Al presente la desinenza cambia in base al soggetto. Per i verbi regolari: parlare → parlo, parli, parla, parliamo, parlate, parlano; prendere → prendo, prendi, prende, prendiamo, prendete, prendono; dormire → dormo, dormi, dorme, dormiamo, dormite, dormono. Essere e avere sono irregolari: sono/sei/è… e ho/hai/ha…'], example: ['Ogni giorno studio italiano, leggo un libro e dormo otto ore. · Noi siamo studenti e abbiamo una lezione.', 'Ogni giorno studio italiano, leggo un libro e dormo otto ore. · Noi siamo studenti e abbiamo una lezione.'], exercises: [exercise('pres-a1-1', ['Choose the correct form: Io ___ italiano.', 'Scegli la forma corretta: Io ___ italiano.'], ['parlo', 'parli', 'parlano'], 0, ['With io, parlare ends in -o: io parlo.', 'Con io, parlare termina in -o: io parlo.']), exercise('pres-a1-2', ['Complete: Tu ___ un libro.', 'Completa: Tu ___ un libro.'], ['leggo', 'leggi', 'leggono'], 1, ['With tu, leggere becomes leggi.', 'Con tu, leggere diventa leggi.']), exercise('pres-a1-3', ['Choose the correct -ire form: Noi ___ bene.', 'Scegli la forma corretta in -ire: Noi ___ bene.'], ['dormite', 'dorme', 'dormiamo'], 2, ['The noi ending is -iamo: noi dormiamo.', 'La desinenza di noi è -iamo: noi dormiamo.']), exercise('pres-a1-4', ['Complete: Maria ___ a scuola.', 'Completa: Maria ___ a scuola.'], ['vado', 'vai', 'va'], 2, ['Maria is lei: andare becomes va.', 'Maria corrisponde a lei: andare diventa va.']), exercise('pres-a1-5', ['Choose the correct form of essere: Noi ___ amici.', 'Scegli la forma corretta di essere: Noi ___ amici.'], ['sono', 'siamo', 'siete'], 1, ['The noi form of essere is siamo.', 'La forma di essere con noi è siamo.']), exercise('pres-a1-6', ['Complete: Loro ___ una macchina.', 'Completa: Loro ___ una macchina.'], ['ha', 'hanno', 'abbiamo'], 1, ['The loro form of avere is hanno.', 'La forma di avere con loro è hanno.']), exercise('pres-a1-7', ['Complete: Tu ___ a casa alle sei.', 'Completa: Tu ___ a casa alle sei.'], ['torno', 'torni', 'torna'], 1, ['With tu, tornare becomes torni.', 'Con tu, tornare diventa torni.']), exercise('pres-a1-8', ['Complete: Voi ___ in Italia.', 'Completa: Voi ___ in Italia.'], ['vivete', 'vivono', 'viviamo'], 0, ['The voi ending of vivere is -ete: vivete.', 'La desinenza di vivere con voi è -ete: vivete.']), exercise('pres-a1-9', ['Complete: Io ___ un caffè.', 'Completa: Io ___ un caffè.'], ['prendo', 'prendi', 'prende'], 0, ['With io, prendere becomes prendo.', 'Con io, prendere diventa prendo.']), exercise('pres-a1-10', ['Complete: Lei ___ in ufficio.', 'Completa: Lei ___ in ufficio.'], ['lavoro', 'lavori', 'lavora'], 2, ['Lei takes the third-person form lavora.', 'Lei richiede la terza persona lavora.']), exercise('pres-a1-11', ['Complete: Noi ___ fame.', 'Completa: Noi ___ fame.'], ['ho', 'abbiamo', 'hanno'], 1, ['The noi form of avere is abbiamo: abbiamo fame.', 'La forma di avere con noi è abbiamo: abbiamo fame.'])] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Common irregular verbs, modal verbs and negative sentences.', 'Verbi irregolari comuni, verbi modali e frasi negative.'], explanation: ['Some frequent verbs have irregular forms: andare → vado, vai, va, andiamo, andate, vanno; fare → faccio, fai, fa, facciamo, fate, fanno; venire → vengo, vieni, viene, veniamo, venite, vengono. Potere, volere and dovere are followed by an infinitive. Put non before the conjugated verb: oggi non esco.', 'Alcuni verbi frequenti hanno forme irregolari: andare → vado, vai, va, andiamo, andate, vanno; fare → faccio, fai, fa, facciamo, fate, fanno; venire → vengo, vieni, viene, veniamo, venite, vengono. Potere, volere e dovere sono seguiti da un infinito. Metti non prima del verbo coniugato: oggi non esco.'], example: ['Oggi vado in biblioteca, ma non posso restare a lungo. Domani faccio i compiti e vengo da te.', 'Oggi vado in biblioteca, ma non posso restare a lungo. Domani faccio i compiti e vengo da te.'], exercises: [exercise('pres-a2-1', ['Complete: Io ___ i compiti dopo cena.', 'Completa: Io ___ i compiti dopo cena.'], ['faccio', 'fai', 'fa'], 0, ['The io form of fare is faccio.', 'La forma di fare con io è faccio.']), exercise('pres-a2-2', ['Choose the correct form: Loro ___ a casa alle sei.', 'Scegli la forma corretta: Loro ___ a casa alle sei.'], ['viene', 'veniamo', 'vengono'], 2, ['The loro form of venire is vengono.', 'La forma di venire con loro è vengono.']), exercise('pres-a2-3', ['Choose the correct modal construction.', 'Scegli la costruzione modale corretta.'], ['Voglio imparare l’italiano.', 'Voglio imparo l’italiano.', 'Volere imparare l’italiano.'], 0, ['A modal verb is followed by an infinitive: voglio imparare.', 'Un verbo modale è seguito da un infinito: voglio imparare.']), exercise('pres-a2-4', ['Where does non go?', 'Dove si mette non?'], ['Non prima del verbo: non capisco.', 'Dopo il verbo: capisco non.', 'Dopo il soggetto e dopo il verbo: capisco io non.'], 0, ['Non normally comes immediately before the conjugated verb.', 'Non si mette normalmente subito prima del verbo coniugato.']), exercise('pres-a2-5', ['Complete: Tu ___ uscire stasera?', 'Completa: Tu ___ uscire stasera?'], ['puoi', 'posso', 'possono'], 0, ['The tu form of potere is puoi.', 'La forma di potere con tu è puoi.']), exercise('pres-a2-6', ['Choose the correct sentence.', 'Scegli la frase corretta.'], ['Oggi non vengo a scuola.', 'Oggi vengo non a scuola.', 'Oggi non venire a scuola.'], 0, ['Non precedes the conjugated verb vengo.', 'Non precede il verbo coniugato vengo.']), exercise('pres-a2-7', ['Complete: Noi ___ al cinema stasera.', 'Completa: Noi ___ al cinema stasera.'], ['andiamo', 'andate', 'vanno'], 0, ['The noi form of andare is andiamo.', 'La forma di andare con noi è andiamo.']), exercise('pres-a2-8', ['Complete: Voi ___ i compiti ora.', 'Completa: Voi ___ i compiti ora.'], ['fate', 'fanno', 'facciamo'], 0, ['The voi form of fare is fate.', 'La forma di fare con voi è fate.']), exercise('pres-a2-9', ['Complete: Io ___ venire domani.', 'Completa: Io ___ venire domani.'], ['devo', 'devi', 'deve'], 0, ['The io form of dovere is devo; a modal is followed by the infinitive.', 'La forma di dovere con io è devo; un modale è seguito dall’infinito.']), exercise('pres-a2-10', ['Choose the correct negative sentence.', 'Scegli la frase negativa corretta.'], ['Oggi non voglio uscire.', 'Oggi voglio non uscire non.', 'Oggi non voglio esco.'], 0, ['Non precedes voglio; the modal is followed by the infinitive uscire.', 'Non precede voglio; il modale è seguito dall’infinito uscire.']), exercise('pres-a2-11', ['Complete: Loro ___ a scuola in bici.', 'Completa: Loro ___ a scuola in bici.'], ['vanno', 'vai', 'andiamo'], 0, ['The loro form of andare is vanno.', 'La forma di andare con loro è vanno.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Use the present accurately in explanations, routines and connected speech.', 'Usa il presente con precisione in spiegazioni, abitudini e discorsi articolati.'], explanation: ['At B1, combine regular and irregular forms with adverbs, time expressions and modal verbs. Italian often omits the subject pronoun; include it when you need contrast or emphasis. Keep the infinitive after a modal verb and place non before the conjugated verb.', 'Al livello B1 combina forme regolari e irregolari con avverbi, espressioni di tempo e verbi modali. In italiano il pronome soggetto spesso si omette; inseriscilo quando serve contrasto o enfasi. Dopo un modale usa l’infinito e colloca non prima del verbo coniugato.'], example: ['Di solito prendo l’autobus, ma oggi preferisco camminare perché posso arrivare in anticipo.', 'Di solito prendo l’autobus, ma oggi preferisco camminare perché posso arrivare in anticipo.'], exercises: [exercise('pres-b1-1', ['Choose the sentence with consistent subject and verb agreement.', 'Scegli la frase con un accordo corretto tra soggetto e verbo.'], ['Io e Marta andiamo in centro.', 'Io e Marta va in centro.', 'Io e Marta andate in centro.'], 0, ['Io e Marta means noi, so use andiamo.', 'Io e Marta significa noi, quindi si usa andiamo.']), exercise('pres-b1-2', ['Choose the natural negative modal sentence.', 'Scegli la frase negativa con il modale più naturale.'], ['Non posso venire domani.', 'Posso non venire domani non.', 'Non posso vengo domani.'], 0, ['Non precedes posso, and venire remains in the infinitive.', 'Non precede posso e venire resta all’infinito.']), exercise('pres-b1-3', ['Choose the sentence where the subject pronoun adds contrast.', 'Scegli la frase in cui il pronome soggetto esprime contrasto.'], ['Io preferisco il tè, mentre lui preferisce il caffè.', 'Io preferisco il tè, mentre lui preferisco il caffè.', 'Io preferisce il tè, mentre lui preferisce il caffè.'], 0, ['The pronouns io and lui make the contrast clear; the verbs agree with each subject.', 'I pronomi io e lui rendono chiaro il contrasto; i verbi concordano con ciascun soggetto.']), exercise('pres-b1-4', ['Choose the sentence with correct agreement.', 'Scegli la frase con l’accordo corretto.'], ['Tu e Luca venite alla festa?', 'Tu e Luca vieni alla festa?', 'Tu e Luca vengono alla festa?'], 0, ['Tu e Luca means voi: venite.', 'Tu e Luca significa voi: venite.']), exercise('pres-b1-5', ['Choose the natural sentence with a modal.', 'Scegli la frase naturale con un modale.'], ['Non posso uscire perché devo studiare.', 'Non posso esco perché devo studio.', 'Posso non uscire perché devo studiare non.'], 0, ['Both modals are followed by the infinitive; non precedes the conjugated verb.', 'Entrambi i modali sono seguiti dall’infinito; non precede il verbo coniugato.'])] }
    }
  },

  {
    id: 'imperfetto', title: { en: 'Imperfect tense · Imperfetto', it: 'Imperfetto', pt: 'Imperfeito · Imperfetto', es: 'Imperfecto · Imperfetto', fr: 'Imparfait · Imperfetto', de: 'Imperfekt · Imperfetto' }, subtitle: { en: 'Describe past habits, ongoing situations and background.', it: 'Descrivi abitudini passate, situazioni in corso e contesti.', pt: 'Descreva hábitos passados, situações em curso e contexto.', es: 'Describe hábitos pasados, situaciones en curso y contexto.', fr: 'Décris des habitudes passées, des situations en cours et le contexte.', de: 'Beschreibe frühere Gewohnheiten, laufende Situationen und den Hintergrund.' },
    levels: {
      A1: { label: { en: 'First steps', it: 'Primi passi', pt: 'Primeiros passos', es: 'Primeros pasos', fr: 'Premiers pas', de: 'Erste Schritte' }, focus: ['Recognise common forms such as ero, era, avevo and c’era.', 'Riconosci forme comuni come ero, era, avevo e c’era.'], explanation: ['The imperfetto is used for past situations and repeated actions. Start by recognising essere (ero, eri, era, eravamo, eravate, erano) and avere (avevo, avevi, aveva, avevamo, avevate, avevano). C’era means “there was”; c’erano means “there were”.', 'L’imperfetto si usa per situazioni passate e azioni abituali. Inizia riconoscendo essere (ero, eri, era, eravamo, eravate, erano) e avere (avevo, avevi, aveva, avevamo, avevate, avevano). C’era significa “there was”; c’erano significa “there were”.'], example: ['Da piccolo ero timido e avevo un cane. In giardino c’erano molti alberi.', 'Da piccolo ero timido e avevo un cane. In giardino c’erano molti alberi.'], exercises: [exercise('imp-a1-1', ['Choose the correct form: Quando ero piccolo, io ___ un cane.', 'Scegli la forma corretta: Quando ero piccolo, io ___ un cane.'], ['avevo', 'avevi', 'avevano'], 0, ['With io, avere in the imperfetto is avevo.', 'Con io, avere all’imperfetto diventa avevo.']), exercise('imp-a1-2', ['Complete: Ieri il tempo ___ bello.', 'Completa: Ieri il tempo ___ bello.'], ['era', 'ero', 'eravamo'], 0, ['Il tempo is third-person singular: era.', 'Il tempo è terza persona singolare: era.']), exercise('imp-a1-3', ['Choose the meaning of c’era.', 'Scegli il significato di c’era.'], ['There were', 'There was', 'There will be'], 1, ['C’era is singular and means “there was”.', 'C’era è singolare e significa “there was”.']), exercise('imp-a1-4', ['Complete: Da bambini noi ___ felici.', 'Completa: Da bambini noi ___ felici.'], ['eravate', 'eravamo', 'erano'], 1, ['The noi form of essere is eravamo.', 'La forma di essere con noi è eravamo.']), exercise('imp-a1-5', ['Choose the plural form: Nel parco ___ molti bambini.', 'Scegli la forma plurale: Nel parco ___ molti bambini.'], ['c’era', 'c’erano', 'c’è'], 1, ['C’erano agrees with the plural noun bambini.', 'C’erano concorda con il nome plurale bambini.']), exercise('imp-a1-6', ['Complete: Tu ___ sempre fame da piccolo.', 'Completa: Tu ___ sempre fame da piccolo.'], ['avevo', 'avevi', 'aveva'], 1, ['The tu form of avere is avevi.', 'La forma di avere con tu è avevi.']), exercise('imp-a1-7', ['Complete: Io ___ felice da bambino.', 'Completa: Io ___ felice da bambino.'], ['ero', 'eri', 'era'], 0, ['The io form of essere in the imperfetto is ero.', 'La forma di essere all’imperfetto con io è ero.']), exercise('imp-a1-8', ['Complete: Voi ___ a scuola insieme.', 'Completa: Voi ___ a scuola insieme.'], ['eravate', 'eravamo', 'erano'], 0, ['The voi form of essere in the imperfetto is eravate.', 'La forma di essere all’imperfetto con voi è eravate.']), exercise('imp-a1-9', ['Choose the meaning of c’erano.', 'Scegli il significato di c’erano.'], ['There was', 'There were', 'There is'], 1, ['C’erano is plural: there were.', 'C’erano è plurale: there were.']), exercise('imp-a1-10', ['Complete: Lui ___ sempre sonno.', 'Completa: Lui ___ sempre sonno.'], ['avevo', 'aveva', 'avevi'], 1, ['The lui form of avere in the imperfetto is aveva.', 'La forma di avere all’imperfetto con lui è aveva.']), exercise('imp-a1-11', ['Complete: Loro ___ in campagna d’estate.', 'Completa: Loro ___ in campagna d’estate.'], ['erano', 'eravamo', 'era'], 0, ['The loro form of essere in the imperfetto is erano.', 'La forma di essere all’imperfetto con loro è erano.'])] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Form regular imperfect verbs and describe habits or ongoing past actions.', 'Forma verbi regolari all’imperfetto e descrivi abitudini o azioni passate in corso.'], explanation: ['For regular verbs, remove -are, -ere or -ire and add -avo/-avi/-ava/-avamo/-avate/-avano, -evo… or -ivo…. Use the imperfetto for habits (ogni estate andavo al mare), descriptions (era caldo) and actions in progress (mentre studiavo).', 'Per i verbi regolari, togli -are, -ere o -ire e aggiungi -avo/-avi/-ava/-avamo/-avate/-avano, -evo… oppure -ivo…. Usa l’imperfetto per abitudini (ogni estate andavo al mare), descrizioni (faceva caldo) e azioni in corso (mentre studiavo).'], example: ['Ogni estate andavo al mare e leggevo molti libri. Mentre studiavo, ascoltavo la musica.', 'Ogni estate andavo al mare e leggevo molti libri. Mentre studiavo, ascoltavo la musica.'], exercises: [exercise('imp-a2-1', ['Choose the correct form: Da bambina, Marta ___ spesso.', 'Scegli la forma corretta: Da bambina, Marta ___ spesso.'], ['leggeva', 'leggevo', 'leggevano'], 0, ['Marta is lei: leggere becomes leggeva.', 'Marta corrisponde a lei: leggere diventa leggeva.']), exercise('imp-a2-2', ['Complete: Noi ___ a calcio ogni sabato.', 'Completa: Noi ___ a calcio ogni sabato.'], ['giocavate', 'giocavamo', 'giocavano'], 1, ['The noi ending for giocare in the imperfetto is -avamo.', 'La desinenza di giocare con noi all’imperfetto è -avamo.']), exercise('imp-a2-3', ['Choose the sentence describing a past habit.', 'Scegli la frase che descrive un’abitudine passata.'], ['Ieri ho letto un libro.', 'Da piccolo leggevo ogni sera.', 'Domani leggerò un libro.'], 1, ['Da piccolo and ogni sera signal a repeated past habit: leggevo.', 'Da piccolo e ogni sera indicano un’abitudine passata: leggevo.']), exercise('imp-a2-4', ['Complete: Mentre io ___, è arrivato Luca.', 'Completa: Mentre io ___, è arrivato Luca.'], ['studiavo', 'ho studiato', 'studierò'], 0, ['The imperfetto describes the ongoing background action: studiavo.', 'L’imperfetto descrive l’azione di sfondo in corso: studiavo.']), exercise('imp-a2-5', ['Choose the correct -ire form: I bambini ___ nel giardino.', 'Scegli la forma corretta in -ire: I bambini ___ nel giardino.'], ['dormivano', 'dormivamo', 'dormivate'], 0, ['The loro form of dormire in the imperfetto is dormivano.', 'La forma di dormire con loro all’imperfetto è dormivano.']), exercise('imp-a2-6', ['Which ending completes “parl-___” for voi?', 'Quale desinenza completa “parl-___” con voi?'], ['-avate', '-avamo', '-avano'], 0, ['Voi takes -avate: parlavate.', 'Voi richiede -avate: parlavate.']), exercise('imp-a2-7', ['Complete: Da piccolo io ___ molti cartoni.', 'Completa: Da piccolo io ___ molti cartoni.'], ['guardavo', 'guardavi', 'guardava'], 0, ['The io form of guardare in the imperfetto is guardavo.', 'La forma di guardare all’imperfetto con io è guardavo.']), exercise('imp-a2-8', ['Choose the habitual-past sentence.', 'Scegli la frase di abitudine passata.'], ['Ogni estate andavamo al mare.', 'Ieri siamo andati al mare una volta.', 'Domani andremo al mare.'], 0, ['Ogni estate + imperfetto expresses a repeated past habit.', 'Ogni estate + imperfetto esprime un’abitudine passata.']), exercise('imp-a2-9', ['Complete: Tu ___ sempre tardi a scuola.', 'Completa: Tu ___ sempre tardi a scuola.'], ['arrivavi', 'arrivavo', 'arrivava'], 0, ['The tu form of arrivare in the imperfetto is arrivavi.', 'La forma di arrivare all’imperfetto con tu è arrivavi.']), exercise('imp-a2-10', ['Which ending completes “dorm-___” for noi?', 'Quale desinenza completa “dorm-___” con noi?'], ['-ivamo', '-ivate', '-ivano'], 0, ['Noi takes -ivamo: dormivamo.', 'Noi richiede -ivamo: dormivamo.']), exercise('imp-a2-11', ['Complete: Mentre lei ___, è entrato Marco.', 'Completa: Mentre lei ___, è entrato Marco.'], ['leggeva', 'ha letto', 'leggerà'], 0, ['The imperfetto describes the ongoing action: leggeva.', 'L’imperfetto descrive l’azione in corso: leggeva.'])] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Contrast imperfetto with passato prossimo in narratives.', 'Distingui imperfetto e passato prossimo nei racconti.'], explanation: ['Use the imperfetto for setting, descriptions, habits and actions already in progress; use the passato prossimo for completed events that move the story forward. They often work together: Mentre camminavo, ho incontrato Sara.', 'Usa l’imperfetto per contesto, descrizioni, abitudini e azioni già in corso; usa il passato prossimo per eventi conclusi che fanno avanzare il racconto. Spesso si usano insieme: Mentre camminavo, ho incontrato Sara.'], example: ['Pioveva e tornavo a casa quando ho incontrato un vecchio amico.', 'Pioveva e tornavo a casa quando ho incontrato un vecchio amico.'], exercises: [exercise('imp-b1-1', ['Choose the correct tense contrast.', 'Scegli il contrasto corretto tra i tempi.'], ['Mentre cucinavo, è suonato il telefono.', 'Mentre ho cucinato, suonava il telefono ieri una volta.', 'Mentre cucinerò, è suonato il telefono.'], 0, ['Cucinavo is the ongoing background; è suonato is the completed interrupting event.', 'Cucinavo è l’azione di sfondo in corso; è suonato è l’evento concluso che interrompe.']), exercise('imp-b1-2', ['Choose the natural description of a repeated childhood habit.', 'Scegli la descrizione naturale di un’abitudine ripetuta nell’infanzia.'], ['Da bambino andavo spesso in bicicletta.', 'Da bambino sono andato spesso in bicicletta ogni giorno per anni.', 'Da bambino andrò spesso in bicicletta.'], 0, ['The imperfetto expresses a repeated, habitual action in the past.', 'L’imperfetto esprime un’azione abituale e ripetuta nel passato.']), exercise('imp-b1-3', ['Complete the narrative: La strada ___ deserta quando ___ un rumore.', 'Completa il racconto: La strada ___ deserta quando ___ un rumore.'], ['era / ho sentito', 'è stata / sentivo', 'fu / sentivo'], 0, ['Era describes the background; ho sentito marks the completed event.', 'Era descrive lo sfondo; ho sentito indica l’evento concluso.']), exercise('imp-b1-4', ['Choose the correct tense contrast.', 'Scegli il contrasto corretto tra i tempi.'], ['Dormivo quando ha squillato il telefono.', 'Ho dormito quando squillava il telefono una volta sola.', 'Dormirò quando ha squillato il telefono.'], 0, ['Dormivo is the ongoing background; ha squillato is the completed event.', 'Dormivo è lo sfondo in corso; ha squillato è l’evento concluso.']), exercise('imp-b1-5', ['Complete the narrative: ___ bel tempo, così ___ una passeggiata.', 'Completa il racconto: ___ bel tempo, così ___ una passeggiata.'], ['Faceva / abbiamo fatto', 'Ha fatto / facevamo', 'Fece / facevamo'], 0, ['Faceva describes the background weather; abbiamo fatto is the completed action.', 'Faceva descrive lo sfondo (il tempo); abbiamo fatto è l’azione conclusa.'])] }
    }
  },

  {
    id: 'prepositions', title: { en: 'Prepositions · Preposizioni', it: 'Preposizioni', pt: 'Preposições · Preposizioni', es: 'Preposiciones · Preposizioni', fr: 'Prépositions · Preposizioni', de: 'Präpositionen · Preposizioni' }, subtitle: { en: 'Choose the right preposition for places, movement and everyday relationships.', it: 'Scegli la preposizione corretta per luoghi, spostamenti e relazioni quotidiane.', pt: 'Escolha a preposição certa para lugares, movimento e relações do dia a dia.', es: 'Elige la preposición correcta para lugares, movimiento y relaciones cotidianas.', fr: 'Choisis la bonne préposition pour les lieux, le mouvement et les relations quotidiennes.', de: 'Wähle die richtige Präposition für Orte, Bewegung und alltägliche Beziehungen.' },
    levels: {
      A1: { label: { en: 'Foundations', it: 'Fondamenti', pt: 'Fundamentos', es: 'Fundamentos', fr: 'Fondamentaux', de: 'Grundlagen' }, focus: ['Common simple prepositions: a, in, di, da, con, per and su.', 'Preposizioni semplici più comuni: a, in, di, da, con, per e su.'], explanation: ['Prepositions connect words and show relationships. Use a with cities (a Roma), in with many countries and regions (in Italia), di for origin or possession (di Marco), da for a person or starting point (da Luca), con for company or means (con Sara), per for purpose or destination (per scuola), and su for position (sul tavolo).', 'Le preposizioni collegano le parole e indicano relazioni. Usa a con le città (a Roma), in con molti Paesi e regioni (in Italia), di per origine o possesso (di Marco), da con una persona o un punto di partenza (da Luca), con per compagnia o mezzo (con Sara), per per uno scopo o una destinazione (per scuola) e su per la posizione (sul tavolo).'], example: ['Abito a Roma, vengo dall’Italia, vado da Marco con il bus.', 'Abito a Roma, vengo dall’Italia, vado da Marco con il bus.'], exercises: [
        exercise('prep-a1-1', ['Complete: Vivo ___ Roma.', 'Completa: Vivo ___ Roma.'], ['a', 'in', 'da'], 0, ['Use a with the name of a city: a Roma.', 'Si usa a con il nome di una città: a Roma.']),
        exercise('prep-a1-2', ['Complete: Abito ___ Italia.', 'Completa: Abito ___ Italia.'], ['a', 'in', 'di'], 1, ['Use in with the name of a country: in Italia.', 'Si usa in con il nome di un Paese: in Italia.']),
        exercise('prep-a1-3', ['Complete: Questo libro è ___ Giulia.', 'Completa: Questo libro è ___ Giulia.'], ['con', 'di', 'per'], 1, ['Di can show possession: il libro di Giulia.', 'Di può indicare il possesso: il libro di Giulia.']),
        exercise('prep-a1-4', ['Complete: Oggi vado ___ Luca.', 'Completa: Oggi vado ___ Luca.'], ['da', 'in', 'su'], 0, ['Use da when going to a person’s home or workplace: da Luca.', 'Si usa da per indicare che si va a casa o sul posto di lavoro di una persona: da Luca.']),
        exercise('prep-a1-5', ['Complete: Studio italiano ___ mia sorella.', 'Completa: Studio italiano ___ mia sorella.'], ['per', 'con', 'di'], 1, ['Con means together with: con mia sorella.', 'Con significa insieme a: con mia sorella.']),
        exercise('prep-a1-6', ['Complete: Le chiavi sono ___ tavolo.', 'Completa: Le chiavi sono ___ tavolo.'], ['su', 'da', 'a'], 0, ['Su indicates position on a surface; su + il becomes sul.', 'Su indica la posizione sopra una superficie; su + il diventa sul.']), exercise('prep-a1-7', ['Complete: Vado ___ scuola a piedi.', 'Completa: Vado ___ scuola a piedi.'], ['a', 'in', 'di'], 0, ['A is used in the fixed phrase andare a scuola.', 'A si usa nell’espressione fissa andare a scuola.']), exercise('prep-a1-8', ['Complete: Il libro è ___ tavolo.', 'Completa: Il libro è ___ tavolo.'], ['su', 'in', 'da'], 0, ['Su indicates position on a surface (su + il = sul).', 'Su indica la posizione su una superficie (su + il = sul).']), exercise('prep-a1-9', ['Complete: Vengo ___ Francia.', 'Completa: Vengo ___ Francia.'], ['da', 'di', 'a'], 0, ['Da indicates origin from a country with venire: vengo dalla Francia.', 'Da indica la provenienza da un Paese con venire: vengo dalla Francia.']), exercise('prep-a1-10', ['Complete: Questo regalo è ___ te.', 'Completa: Questo regalo è ___ te.'], ['per', 'di', 'con'], 0, ['Per expresses the recipient/purpose: per te.', 'Per esprime il destinatario/scopo: per te.']), exercise('prep-a1-11', ['Complete: Parlo ___ telefono con Anna.', 'Completa: Parlo ___ telefono con Anna.'], ['al', 'in', 'da'], 0, ['The fixed phrase is al telefono.', 'L’espressione fissa è al telefono.'])
      ] },
      A2: { label: { en: 'Application', it: 'Applicazione', pt: 'Aplicação', es: 'Aplicación', fr: 'Application', de: 'Anwendung' }, focus: ['Prepositions with common places, time expressions and articulated forms.', 'Preposizioni con luoghi comuni, espressioni di tempo e forme articolate.'], explanation: ['Some prepositions combine with definite articles: a + il = al, in + il = nel, di + la = della, da + gli = dagli. Learn common patterns: al cinema, in biblioteca, nel pomeriggio, alle otto, dal medico. The correct choice often depends on the expression, so learn useful phrases as whole chunks.', 'Alcune preposizioni si uniscono agli articoli determinativi: a + il = al, in + il = nel, di + la = della, da + gli = dagli. Impara espressioni comuni: al cinema, in biblioteca, nel pomeriggio, alle otto, dal medico. La scelta corretta spesso dipende dall’espressione: impara le combinazioni più utili come gruppi di parole.'], example: ['Vado al cinema alle otto e torno nel pomeriggio.', 'Vado al cinema alle otto e torno nel pomeriggio.'], exercises: [
        exercise('prep-a2-1', ['Complete: Andiamo ___ cinema stasera.', 'Completa: Andiamo ___ cinema stasera.'], ['al', 'in', 'da'], 0, ['A + il becomes al: al cinema.', 'A + il diventa al: al cinema.']),
        exercise('prep-a2-2', ['Complete: La lezione comincia ___ otto.', 'Completa: La lezione comincia ___ otto.'], ['alle', 'agli', 'nella'], 0, ['Use alle with clock times: alle otto.', 'Si usa alle con gli orari: alle otto.']),
        exercise('prep-a2-3', ['Complete: I bambini giocano ___ giardino.', 'Completa: I bambini giocano ___ giardino.'], ['nel', 'al', 'dallo'], 0, ['In + il becomes nel when describing location inside the garden.', 'In + il diventa nel per indicare che si è dentro il giardino.']),
        exercise('prep-a2-4', ['Choose the natural phrase.', 'Scegli l’espressione naturale.'], ['in biblioteca', 'a biblioteca', 'da biblioteca'], 0, ['The usual expression for being or going to the library is in biblioteca.', 'L’espressione abituale per indicare che si è o si va in biblioteca è in biblioteca.']),
        exercise('prep-a2-5', ['Complete: Domani devo andare ___ medico.', 'Completa: Domani devo andare ___ medico.'], ['dal', 'nel', 'sul'], 0, ['Da + il becomes dal: andare dal medico.', 'Da + il diventa dal: andare dal medico.']),
        exercise('prep-a2-6', ['Complete: Il quaderno ___ studentessa è qui.', 'Completa: Il quaderno ___ studentessa è qui.'], ['della', 'alla', 'nella'], 0, ['Di + la becomes della to show possession: della studentessa.', 'Di + la diventa della per indicare il possesso: della studentessa.']), exercise('prep-a2-7', ['Complete: Torno ___ pomeriggio.', 'Completa: Torno ___ pomeriggio.'], ['nel', 'al', 'dal'], 0, ['The fixed time phrase is nel pomeriggio.', 'L’espressione di tempo fissa è nel pomeriggio.']), exercise('prep-a2-8', ['Complete: Il regalo ___ bambini è pronto.', 'Completa: Il regalo ___ bambini è pronto.'], ['dei', 'degli', 'delle'], 0, ['Di + i becomes dei: il regalo dei bambini.', 'Di + i diventa dei: il regalo dei bambini.']), exercise('prep-a2-9', ['Complete: Vado ___ stazione.', 'Completa: Vado ___ stazione.'], ['in', 'a', 'da'], 0, ['The usual phrase is in stazione.', 'L’espressione abituale è in stazione.']), exercise('prep-a2-10', ['Complete: Esco ___ casa alle otto.', 'Completa: Esco ___ casa alle otto.'], ['di', 'da', 'in'], 0, ['The fixed phrase is uscire di casa.', 'L’espressione fissa è uscire di casa.']), exercise('prep-a2-11', ['Complete: Il treno parte ___ nove.', 'Completa: Il treno parte ___ nove.'], ['alle', 'nelle', 'dalle'], 0, ['Clock times use alle: alle nove.', 'Gli orari usano alle: alle nove.'])
      ] },
      B1: { label: { en: 'Mastery', it: 'Padronanza', pt: 'Domínio', es: 'Dominio', fr: 'Maîtrise', de: 'Beherrschung' }, focus: ['Distinguish prepositions in longer sentences and fixed expressions.', 'Distingui le preposizioni nelle frasi più lunghe e nelle espressioni fisse.'], explanation: ['At B1, pay attention to meaning and fixed combinations. Pensare a means to think about; parlare di means to talk about; dipendere da means to depend on. Some verbs require a particular preposition, so learn the verb and its preposition together.', 'Al livello B1 presta attenzione al significato e alle combinazioni fisse. Pensare a, parlare di e dipendere da richiedono preposizioni specifiche. Alcuni verbi richiedono una determinata preposizione: impara insieme il verbo e la sua preposizione.'], example: ['Penso spesso a quel viaggio e parlo di quel progetto con i colleghi.', 'Penso spesso a quel viaggio e parlo di quel progetto con i colleghi.'], exercises: [
        exercise('prep-b1-1', ['Complete: Penso spesso ___ te.', 'Completa: Penso spesso ___ te.'], ['a', 'di', 'da'], 0, ['Pensare a is the standard construction for thinking about someone or something.', 'Pensare a è la costruzione standard per riflettere su una persona o una cosa.']),
        exercise('prep-b1-2', ['Complete: Dipende ___ quanto tempo abbiamo.', 'Completa: Dipende ___ quanto tempo abbiamo.'], ['da', 'a', 'con'], 0, ['Dipendere takes da: dipende da quanto tempo abbiamo.', 'Dipendere richiede da: dipende da quanto tempo abbiamo.']),
        exercise('prep-b1-3', ['Choose the correct sentence.', 'Scegli la frase corretta.'], ['Parliamo del problema domani.', 'Parliamo al problema domani.', 'Parliamo dal problema domani.'], 0, ['Parlare di means to talk about; di + il becomes del.', 'Parlare di significa parlare di qualcosa; di + il diventa del.']), exercise('prep-b1-4', ['Complete: Mi fido ___ te.', 'Completa: Mi fido ___ te.'], ['di', 'a', 'da'], 0, ['Fidarsi takes di: mi fido di te.', 'Fidarsi richiede di: mi fido di te.']), exercise('prep-b1-5', ['Complete: Riesco ___ finire il lavoro.', 'Completa: Riesco ___ finire il lavoro.'], ['a', 'di', 'da'], 0, ['Riuscire takes a + infinitive: riesco a finire.', 'Riuscire richiede a + infinito: riesco a finire.'])
      ] }
    }
  },
  {
    id:'adjective-agreement', title:{ en: 'Adjective agreement · Accordo degli aggettivi', it: 'Accordo degli aggettivi', pt: 'Concordância do adjetivo · Accordo degli aggettivi', es: 'Concordancia del adjetivo · Accordo degli aggettivi', fr: 'Accord de l’adjectif · Accordo degli aggettivi', de: 'Adjektiv-Angleichung · Accordo degli aggettivi' }, subtitle:{ en: 'Match adjectives to noun gender and number.', it: 'Fai concordare gli aggettivi con genere e numero del nome.', pt: 'Faça o adjetivo concordar em gênero e número com o substantivo.', es: 'Haz que el adjetivo concuerde en género y número con el sustantivo.', fr: 'Accorde l’adjectif en genre et en nombre avec le nom.', de: 'Gleiche das Adjektiv in Geschlecht und Zahl an das Substantiv an.' },
    levels:{
      A1:{label:['Foundations','Fondamenti'],focus:['Masculine/feminine and singular/plural endings.','Desinenze maschili/femminili e singolari/plurali.'],explanation:['Most adjectives change to match the noun: ragazzo alto, ragazza alta, ragazzi alti, ragazze alte. Adjectives ending in -e keep the same singular form for both genders: gentile; the plural is gentili.','La maggior parte degli aggettivi cambia per concordare con il nome: ragazzo alto, ragazza alta, ragazzi alti, ragazze alte. Gli aggettivi in -e mantengono la stessa forma singolare per entrambi i generi: gentile; il plurale è gentili.'],example:['Un ragazzo simpatico · una ragazza simpatica · due ragazze simpatiche.','Un ragazzo simpatico · una ragazza simpatica · due ragazze simpatiche.'],exercises:[
        exercise('adj-a1-1',['Choose: una casa ___.','Scegli: una casa ___.'],['grande','grandi','grando'],0,['Casa is feminine singular; grande is the correct singular form.','Casa è femminile singolare; grande è la forma singolare corretta.']),
        exercise('adj-a1-2',['Complete: un ragazzo ___.','Completa: un ragazzo ___.'],['alta','alto','alti'],1,['Ragazzo is masculine singular: alto.','Ragazzo è maschile singolare: alto.']),
        exercise('adj-a1-3',['Complete: due libri ___.','Completa: due libri ___.'],['nuovo','nuove','nuovi'],2,['Libri is masculine plural: nuovi.','Libri è maschile plurale: nuovi.']), exercise('adj-a1-4',['Complete: una ragazza ___.','Completa: una ragazza ___.'],['alto','alta','alti'],1,['Ragazza is feminine singular: alta.','Ragazza è femminile singolare: alta.']), exercise('adj-a1-5',['Complete: le case ___.','Completa: le case ___.'],['bianco','bianche','bianchi'],1,['Case is feminine plural: bianche.','Case è femminile plurale: bianche.']), exercise('adj-a1-6',['Complete: un gatto ___.','Completa: un gatto ___.'],['nera','nero','neri'],1,['Gatto is masculine singular: nero.','Gatto è maschile singolare: nero.']), exercise('adj-a1-7',['Complete: le ragazze sono ___.','Completa: le ragazze sono ___.'],['simpatico','simpatiche','simpatici'],1,['Ragazze is feminine plural: simpatiche.','Ragazze è femminile plurale: simpatiche.']), exercise('adj-a1-8',['Complete: i cani sono ___.','Completa: i cani sono ___.'],['piccoli','piccole','piccola'],0,['Cani is masculine plural: piccoli.','Cani è maschile plurale: piccoli.']), exercise('adj-a1-9',['Choose the -e adjective form: una persona ___.','Scegli la forma in -e: una persona ___.'],['gentile','gentila','gentili'],0,['Gentile keeps one singular form for both genders.','Gentile mantiene un’unica forma singolare per entrambi i generi.']), exercise('adj-a1-10',['Complete: un libro ___.','Completa: un libro ___.'],['rossa','rosso','rosse'],1,['Libro is masculine singular: rosso.','Libro è maschile singolare: rosso.'])]},
      A2:{label:['Application','Applicazione'],focus:['-e adjectives and mixed groups.','Aggettivi in -e e gruppi misti.'],explanation:['Adjectives ending in -e change to -i in the plural: un film interessante, due film interessanti. A mixed group normally takes the masculine plural: Marco e Anna sono contenti.','Gli aggettivi in -e cambiano in -i al plurale: un film interessante, due film interessanti. Un gruppo misto normalmente richiede il maschile plurale: Marco e Anna sono contenti.'],example:['Una lezione interessante · due lezioni interessanti · Paolo e Sara sono contenti.','Una lezione interessante · due lezioni interessanti · Paolo e Sara sono contenti.'],exercises:[
        exercise('adj-a2-1',['Choose the plural: due esercizi ___.','Scegli il plurale: due esercizi ___.'],['difficile','difficili','difficila'],1,['Difficile becomes difficili in the plural.','Difficile diventa difficili al plurale.']),
        exercise('adj-a2-2',['Complete: Anna e Giulia sono ___.','Completa: Anna e Giulia sono ___.'],['felice','felici','felicei'],1,['The plural of felice is felici.','Il plurale di felice è felici.']),
        exercise('adj-a2-3',['Paolo e Marta sono ___.','Paolo e Marta sono ___.'],['stanche','stanchi','stanco'],1,['A mixed group normally takes the masculine plural: stanchi.','Un gruppo misto normalmente richiede il maschile plurale: stanchi.']), exercise('adj-a2-4',['Complete: Marco e Anna sono ___.','Completa: Marco e Anna sono ___.'],['contente','contenti','contento'],1,['A mixed-gender group takes the masculine plural: contenti.','Un gruppo misto richiede il maschile plurale: contenti.']), exercise('adj-a2-5',['Complete the -e plural: due città ___.','Completa il plurale in -e: due città ___.'],['grande','grandi','grande'],1,['Grande becomes grandi in the plural.','Grande diventa grandi al plurale.']), exercise('adj-a2-6',['Complete: le lezioni sono ___.','Completa: le lezioni sono ___.'],['interessante','interessanti','interessante'],1,['-e adjectives become -i in the plural: interessanti.','Gli aggettivi in -e diventano -i al plurale: interessanti.']), exercise('adj-a2-7',['Complete: Sara e Luca sono ___.','Completa: Sara e Luca sono ___.'],['alte','alti','alto'],1,['A mixed group takes masculine plural: alti.','Un gruppo misto richiede il maschile plurale: alti.']), exercise('adj-a2-8',['Complete: dei film ___.','Completa: dei film ___.'],['divertente','divertenti','divertento'],1,['-e adjective plural is divertenti.','Il plurale dell’aggettivo in -e è divertenti.']), exercise('adj-a2-9',['Complete: una storia ___.','Completa: una storia ___.'],['triste','trista','tristi'],0,['Triste is an -e adjective, singular for both genders.','Triste è un aggettivo in -e, singolare per entrambi i generi.']), exercise('adj-a2-10',['Complete: le mele sono ___.','Completa: le mele sono ___.'],['verdi','verde','verda'],0,['-e adjective plural: verdi.','Plurale dell’aggettivo in -e: verdi.'])]},
      B1:{label:['Mastery','Padronanza'],focus:['Agreement in longer phrases and adjective position.','Accordo nei gruppi più lunghi e posizione dell’aggettivo.'],explanation:['Keep agreement consistent across the noun phrase. Position can change meaning: un vecchio amico usually means a long-standing friend; un amico vecchio describes an elderly friend.','Mantieni l’accordo in tutto il gruppo nominale. La posizione può cambiare il significato: un vecchio amico indica un amico di lunga data; un amico vecchio descrive un amico anziano.'],example:['Abbiamo incontrato due vecchie amiche molto gentili.','Abbiamo incontrato due vecchie amiche molto gentili.'],exercises:[
        exercise('adj-b1-1',['Choose the correct phrase.','Scegli il gruppo corretto.'],['Le nuove studentesse sono preparate.','Le nuovi studentesse sono preparati.','La nuove studentesse sono preparata.'],0,['All forms agree in feminine plural.','Tutte le forme concordano al femminile plurale.']),
        exercise('adj-b1-2',['“Un vecchio amico” usually means…','“Un vecchio amico” significa di solito…'],['An elderly friend','A long-standing friend','A young friend'],1,['Before the noun, vecchio often means long-standing.','Prima del nome, vecchio spesso significa che l’amicizia dura da tempo.']),
        exercise('adj-b1-3',['Complete: due città ___.','Completa: due città ___.'],['antico','antiche','antichi'],1,['Città is feminine; its plural adjective is antiche.','Città è femminile; il plurale dell’aggettivo è antiche.']), exercise('adj-b1-4',['Choose the fully correct phrase.','Scegli il gruppo completamente corretto.'],['le grandi città italiane','le grande città italiani','le grandi città italiani'],0,['Grandi (plural) + città (fem. pl.) + italiane (fem. pl.) all agree.','Grandi (plurale) + città (femm. pl.) + italiane (femm. pl.) concordano tutti.']), exercise('adj-b1-5',['Choose the correct agreement with a mixed group.','Scegli l’accordo corretto con un gruppo misto.'],['I ragazzi e le ragazze sono stanchi.','I ragazzi e le ragazze sono stanche.','I ragazzi e le ragazze sono stanco.'],0,['A mixed group defaults to masculine plural: stanchi.','Un gruppo misto richiede il maschile plurale: stanchi.'])]}
    }
  },

];

export const getGrammarTopic = (id: string): GrammarTopic | undefined =>
  ITALIAN_GRAMMAR_TOPICS.find(topic => topic.id === id);
